INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GD-01', 'success', '[arbiter.place(presence_chip, district=deed.district, faction=holding, count=1),\n               arbiter.place(structure_block, district=deed.district, faction=holding, count=1),\n               arbiter.remove(structure_block, district=deed.district, faction=trigger.faction, count=1)]', '04___Card_System___Part1_Core.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GD-01', 'successcrit', 'None', '04___Card_System___Part1_Core.md');
