INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.11', 'cost', 'Mandate * 1 + faction.acting.native * 1', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.11', 'success', 'game.lock(Accord(named), until=game.end OR Accord(named).breach_by_party)', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.11', 'successcrit', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.11', 'fail', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.11', 'failcrit', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.11', 'portrait', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.11', 'narrative', '\"The agreement stands. Whatever your reasons for wanting out, the record disagrees.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.11', 'perspectives', '{\n        Directorate: \"The agreement is now a matter of institutional record. Dissolution would require a filing no one is prepared to make.\",\n        Ghost:       \"The paperwork has been submitted. Quietly. Neither party knows who filed it.\",\n        Syndicate:   \"We have an interest in this arrangement continuing. Our lawyers agree.\",\n        Network:     \"We have made this agreement part of the public record. Dissolving it now would be a story.\",\n        Collective:  \"We hold both parties to what they agreed to. The community remembers.\",\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.11', 'design_note', '\"Any faction with a stake in an active Accord can lock it against voluntary dissolution. Cost: 1 Mandate + 1 faction native resource. Lock persists until game end or direct breach by Accord parties — breach not blocked, consequences apply normally.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.11', 'arbiter_note', '\"ARBITER annotates the named Accord document at Beat 3 — writes \'cannot voluntarily dissolve\' or marks equivalent field on the Accord blank (TBD Art 06). No new component. Annotation is public; faction players enforce. Annotation is voided if either party directly breaches the Accord terms — breach consequences apply normally. Acting faction identity is not announced at resolution.\"', '04___Card_System___Part2_Standard.md');
