INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.12', 'narrative', '\"There are no walls. There are only varying degrees of access.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.12', 'perspectives', '{}', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.12', 'design_note', '\"Scope: CA-inclusive — targets Block/Protect plays in both the Faction Resolution Grid (Type A CMs, Protect/Fortify modifier plays) and ARBITER\'s covert resolution grid (Beat 2 CA cards with function=Block or function=Protect). Cannot target Type B Countermeasures (faction defense — reduces difficulty, not a Block/Protect play). Intel token consumed is any held token.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.12', 'arbiter_note', '\"At Beat 2 resolution: sweep both grid domains. (1) Faction Resolution Grid: discard any Type A Countermeasure or Protect/Fortify modifier play targeting the named district. (2) Covert grid: discard any Beat 2 CA with function=Block or function=Protect from the named district row. Resources committed to discarded cards are not refunded. Operations those cards would have affected proceed without the modifier.\"', '04___Card_System___Part2_Standard.md');
