INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.13', 'success', '(faction(target).standing.remove(2), faction(acting).standing.add(1))', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.13', 'successcrit', 'None', '04___Card_System___Part2_Standard.md');
