INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.13', 'failcrit', '(\n        faction(acting).standing.remove(2),\n        arbiter.dispatch(NotificationSlip(type=\"Disinformation Campaign\", district=target_district), target_faction),\n    )', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.13', 'portrait', '{\n        Network:     PortraitEntry(submitter=+1),\n        Ghost:       PortraitEntry(submitter=-1),\n        Directorate: PortraitEntry(submitter=-1),\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.13', 'narrative', '\"The city\'s opinion is infrastructure. It can be built. It can be demolished.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.13', 'perspectives', '{\n        Guild:       \"Narrative operations are not our toolset. We notice the shift after the quarter closes.\",\n        Directorate: \"Covert image manipulation conflicts with the institutional legitimacy we exist to uphold. We note who deploys it.\",\n        Network:     \"We have channels built for exactly this. Using them properly is what separates signal from noise.\",\n        Ghost:       \"A successful operation leaves no signature. Campaigns draw attention. This is the compromise.\",\n        Syndicate:   \"Standing shifts move markets and tables. We note who runs this and in which districts.\",\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.13', 'design_note', '\"First Standard covert card with PS shift as primary effect — fills Standing/Shift coverage gap. Presence restriction: must have operational footprint to run local narrative operation. Success swing: target −2 PS, acting +1 PS (net 3). Fail: acting −1 PS. Failcrit: acting −2 PS + NotificationSlip to target (campaign ran against you in [district] this Month; not who ran it). Ring modifier: harder in Core (denser institutional oversight). Standard equivalents under Principle 17: Network and Ghost have superior faction-specific versions.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.13', 'arbiter_note', '\"Beat 0: confirm acting faction has presence (token or deployment marker) in target district; if not — op voided, resources returned. Beat 3: roll d100. Success: target −2 PS, acting +1 PS. Fail: acting −1 PS. Fail crit (01–05): acting −2 PS; dispatch NotificationSlip to target faction (\'A disinformation campaign was run against you in [district] this Month\'). Target does not learn who ran it.\"', '04___Card_System___Part2_Standard.md');
