INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.14', 'portrait', '{\n        Ghost:   PortraitEntry(submitter=+1),\n        Network: PortraitEntry(submitter=-1),\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.14', 'narrative', '\"What the record does not contain cannot be verified.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.14', 'perspectives', '{\n        Guild:       \"Operational evidence is a fact of the city. We account for what we do. Who removes the accounting is who fears it.\",\n        Directorate: \"The record exists for a reason. Selectively removing it undermines the institutional process we exist to uphold.\",\n        Network:     \"Every destroyed token is a story that will never be told. That is not intelligence. That is erasure.\",\n        Ghost:       \"Evidence that does not exist cannot follow you. This is the most important lesson we teach.\",\n        Syndicate:   \"Market intelligence has a half-life. The fastest way to extend it is to reduce the competition\'s supply.\",\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.14', 'design_note', '\"Standard covert op targeting an opponent\'s Intel token supply via blind random removal — ARBITER draws one token from target\'s supply without acting faction specifying which. No district restriction; no affinity (destroying evidence has no faction-native doctrine edge). Silent on success: target receives no notification. Automatic fail if target holds no tokens at Beat 3 (cost sunk).\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.14', 'arbiter_note', '\"Covert Dispatch: acting faction names target faction. Beat 3: if target faction holds zero Intel tokens, op fails (cost sunk; do not announce reason). Otherwise, draw one Intel token at random from target faction\'s supply and remove from play (return to box). Acting faction receives no information about the removed token. Target faction receives no notification.\"', '04___Card_System___Part2_Standard.md');
