INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.15', 'portrait', '{\n        Syndicate:   PortraitEntry(submitter=+1),\n        Guild:       PortraitEntry(submitter=-1),\n        Directorate: PortraitEntry(submitter=-1),\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.15', 'narrative', '\"Information doesn\'t belong to anyone. It belongs to whoever holds it.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.15', 'perspectives', '{\n        Guild:       \"We do not take what others have built. The intelligence they gathered represents real work.\",\n        Directorate: \"Covert acquisition bypasses every sanctioned process for handling intelligence. We treat the result accordingly.\",\n        Network:     \"A token in a different hand does not cease to be information. The question is what it becomes.\",\n        Ghost:       \"Their intelligence is now a liability. Ours is now an asset. The operation is the same.\",\n        Syndicate:   \"Capital intelligence infrastructure exists precisely for this — locating value before the market prices it in.\",\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.15', 'design_note', '\"Economy/Redirect/IntelToken — splits Asset Extraction into two cards. Blind random draw from target\'s supply; acting faction receives token face-down in case, inspects privately at Beat 3 resolution. Target\'s token count decreases visibly (visible resource denial). Ghost affinity (threshold +10): covert acquisition doctrine. Syndicate portrait +1: capital intelligence motivation, no threshold bonus (physical acquisition is not Syndicate-native). Automatic fail if target holds no tokens at Beat 3.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.15', 'arbiter_note', '\"Covert Dispatch: acting faction names target faction. Beat 3: if target faction holds zero Intel tokens, op fails (cost sunk; do not announce reason). Otherwise, draw one Intel token at random from target faction\'s supply. Transfer face-down to acting faction\'s dispatch case — acting faction may inspect privately. Target faction\'s token count decreases by 1 (visible).\"', '04___Card_System___Part2_Standard.md');
