INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.16', 'portrait', '{\n        Syndicate:   PortraitEntry(submitter=+1),\n        Guild:       PortraitEntry(submitter=-1),\n        Directorate: PortraitEntry(submitter=-1),\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.16', 'narrative', '\"They packed for an operation they will never run.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.16', 'perspectives', '{\n        Guild:       \"Tools are built for a purpose. Taking them from someone who made them is not the same as earning them.\",\n        Directorate: \"Seizing operational resources outside any sanctioned process is the definition of what we are here to prevent.\",\n        Network:     \"A modifier card in the wrong hand is a signal on the wrong frequency. It still transmits.\",\n        Ghost:       \"Strip their tactical advantage before they deploy it. The modifier they held is now the one we use.\",\n        Syndicate:   \"Their preparation becomes our edge. That is the nature of capital intelligence — arbitrage at the operational level.\",\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.16', 'design_note', '\"Economy/Redirect/ModifierCard — splits Asset Extraction into two cards alongside Intel Extraction. Blind random draw from target\'s modifier hand; acting faction receives card face-down in case, inspects privately at Beat 3 resolution. Target\'s card count decreases visibly. Ghost affinity (threshold +10); Syndicate portrait +1. Automatic fail if target holds no modifier cards at Beat 3.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.CA.16', 'arbiter_note', '\"Covert Dispatch: acting faction names target faction. Beat 3: if target faction holds zero modifier cards, op fails (cost sunk; do not announce reason). Otherwise, draw one modifier card at random from target faction\'s hand. Transfer face-down to acting faction\'s dispatch case — acting faction may inspect privately. Target faction\'s modifier card count decreases by 1 (visible).\"', '04___Card_System___Part2_Standard.md');
