INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.1', 'portrait', '{\n        Directorate: PortraitEntry(submitter=+1),\n        Ghost:       PortraitEntry(submitter=-1),\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.1', 'ps_framing', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.1', 'narrative', '\"A formal declaration carries weight in New Meridian. Presence on the record is presence that cannot be denied.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.1', 'perspectives', '{\n        Guild:       \"We are here. What we build will say the rest.\",\n        Directorate: \"Formal establishment of operations in this district. The record reflects it.\",\n        Network:     \"Our presence here was always going to be known. This makes it official.\",\n        Ghost:       \"Every formal declaration is a commitment we would rather not have made.\",\n        Syndicate:   \"The first step is always claiming the position. Everything else follows.\",\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.1', 'design_note', '\"Formal declaration of operational presence — Automatic resolution, guaranteed outcome, PS +1 on success, mono-resource cost (2 faction native). Directorate affinity: formal institutional presence declaration has no resource cost against mandate doctrine. Ghost −1: visibility conflicts with concealment doctrine. Ring entry rules still enforced by ARBITER at Beat 0.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.1', 'arbiter_note', '\"Place 2 presence tokens for acting faction in declared district at Beat 4. Apply PS +1 to acting faction. Confirm ring entry requirements at Beat 0 — if not satisfied, PA voided; resources returned; acting faction takes Public Pass.\"', '04___Card_System___Part2_Standard.md');
