INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.2', 'affinity', '(\n        faction(acting) == Network:    threshold += 10,\n        faction(acting) == Directorate: threshold += 10,\n    )', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.2', 'restriction', 'faction(target).influence_tier(target_district) >= Established', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.2', 'cost', 'faction.acting.native * 2', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.2', 'boost', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.2', 'success', '(\n        arbiter.remove(presence_chip, district=target_district, faction=target, count=1),\n        if tie_condition(target_district): arbiter.place(ContestedMarker, target_district),\n        faction(acting).standing.add(1),\n        faction(target).standing.remove(1),\n    )', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.2', 'successcrit', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.2', 'fail', 'faction(acting).standing.remove(1)', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.2', 'failcrit', 'faction(acting).standing.remove(2)', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.2', 'portrait', '{\n        Network:     PortraitEntry(submitter=+1),\n        Directorate: PortraitEntry(submitter=+1),\n        Ghost:       PortraitEntry(submitter=-1),\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.2', 'ps_framing', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.2', 'narrative', '\"A contested district is not a resolved one. Filing a formal challenge makes the dispute legible.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.2', 'perspectives', '{\n        Guild:       \"We would rather build than challenge. But we will not cede ground claimed without cause.\",\n        Directorate: \"A formal challenge is the legitimate mechanism for resolving territorial disputes. We prefer it to ambiguity.\",\n        Network:     \"Presence built on hollow ground should not stand. We will say so publicly.\",\n        Ghost:       \"Public challenges create public attention. Attention is expensive.\",\n        Syndicate:   \"Challenges are leverage. The willingness to file one changes the calculus of every faction at the table.\",\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.2', 'design_note', '\"Formal public challenge to another faction\'s presence — mono-resource cost (2 faction native), base threshold 45. Fail/failcrit penalise the challenger — public challenges are public commitments. Network/Directorate +10 threshold: doctrinal alignment with formal dispute mechanisms. Ghost −1: public confrontation conflicts with concealment doctrine. doctrine_mod: Neighbor +10, Opposed −10 on target faction relationship.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.2', 'arbiter_note', '\"Beat 4. Remove 1 presence token from target faction. Check for tie at highest chip count — if tie at 3+ chips, place Contested marker. PS: acting +1, target −1 on success. Acting −1 on fail. Acting −2 on failcrit (no token removed on fail/failcrit).\"', '04___Card_System___Part2_Standard.md');
