INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.3', 'restriction', '(\n        district(target).faction(acting).presence > 0 and\n        district(target).faction(acting).structure == 0\n    )', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.3', 'cost', 'faction.acting.native * 1 + district.target.native * 1', '04___Card_System___Part2_Standard.md');
