INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.3', 'ps_framing', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.3', 'narrative', '\"Every faction that wants to be taken seriously in New Meridian eventually has to build something where everyone can see it.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.3', 'perspectives', '{\n        Guild:       \"We build in the open because the work is not something we need to hide.\",\n        Directorate: \"Infrastructure serves the mandate. We build when the district requires it and the record supports it.\",\n        Network:     \"Building is a public statement. We attend to what the statement claims.\",\n        Ghost:       \"A structure in public view is a structure we have to account for.\",\n        Syndicate:   \"The public commission is the visible portion of the investment. The value is in what follows.\",\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.3', 'design_note', '\"Public counterpart to STD.CA.1. Same cost; Automatic (no fail risk); PS +1. Guild affinity (district native = 0) on-doctrine. Ghost −1: public structure = permanent commitment against concealment doctrine. Counter to Guild\'s build pace: Directorate DIR.PA.1 (Regulatory Override) raises cost of presence-placement in district (prerequisite for this card); GUI.PA.1 (Civic Works Mandate) can be blocked by DIR.PA.1.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.3', 'arbiter_note', '\"Place 1 structure block for acting faction in declared district at Beat 4. PS +1. Restriction at Beat 0: acting faction must have presence and no existing structure. If restriction fails, PA voided.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.4', 'id', '\"STD.PA.4\"', '04___Card_System___Part2_Standard.md');
