INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.4', 'affinity', '(\n        faction(acting).holds_intel_token(faction=target, age=Fresh): threshold += 15,  \n        faction(acting) == Network:     cost.faction(native) -= 1,\n        faction(acting) == Directorate: cost.faction(native) -= 1,\n    )', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.4', 'restriction', 'target_faction != faction(acting)', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.4', 'cost', 'faction.acting.native * 2', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.4', 'boost', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.4', 'success', '(faction(target).standing.remove(2), faction(acting).standing.add(1))', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.4', 'successcrit', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.4', 'fail', 'faction(acting).standing.remove(1)', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.4', 'failcrit', 'faction(acting).standing.remove(2)', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.4', 'portrait', '{\n        Network:     PortraitEntry(submitter=+1),\n        Directorate: PortraitEntry(submitter=+1),\n        Ghost:       PortraitEntry(submitter=-1),\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.4', 'ps_framing', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.4', 'narrative', '\"A formal accusation in New Meridian is not a rumor. It is a claim that goes into the record and demands a response.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.4', 'perspectives', '{\n        Guild:       \"We do not make accusations we cannot support. But we do not stay silent when the conduct is clear.\",\n        Directorate: \"Formal censure is the legitimate response to misconduct. The mechanism exists for a reason.\",\n        Network:     \"The city deserves to know. We are not making an allegation — we are making a fact public.\",\n        Ghost:       \"Public censure creates public attention. We note that the accusation traces back to whoever filed it.\",\n        Syndicate:   \"Censure is leverage applied publicly. The question is always: what does the target do next?\",\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.4', 'design_note', '\"PS attack card of the standard set. Base threshold 35 — demanding. Fresh Intel token (optional, placed on PA at Art 03 §9.2.0, spent regardless of outcome) provides +15 threshold. Network/Directorate −1 cost each. Fail/failcrit PS penalties punish reckless censure. Ghost −1 portrait: public accusation = self-exposure. PS shifts in success/fail are game effects, not Portrait (DIR.PA.2).\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.4', 'arbiter_note', '\"At Art 03 §9.2.0: acting faction places PA with Target Profile face-down; Intel token (if submitted) placed on card. At Art 03 §9.4.3.1.1: flip Target Profile face-up; note target faction. Beat 4: threshold = 35 + 15 if Fresh Intel token on card. On success: target −2 PS, acting +1 PS; Intel token spent. On fail: acting −1 PS; Intel token still spent. On failcrit: acting −2 PS.\"', '04___Card_System___Part2_Standard.md');
