INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.5', 'restriction', 'faction(acting).holds_intel_token(faction=target, age__in=[Fresh, Stale])', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.5', 'cost', 'faction.acting.native * 1 + IntelToken(about=faction(target)) * 1', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.5', 'boost', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.5', 'success', '(\n        arbiter.announce(attribution=target_faction, context=intel_token.quarter),\n        faction(target).standing.remove(2),\n        faction(acting).standing.add(2),\n    )', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.5', 'successcrit', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.5', 'fail', 'faction(acting).standing.remove(1)', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.5', 'failcrit', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.5', 'portrait', '{\n        Network: PortraitEntry(submitter=+1),\n        Ghost:   PortraitEntry(submitter=-2),\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.5', 'ps_framing', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.5', 'narrative', '\"In New Meridian, there are very few true secrets. There are only secrets that haven\'t been made public yet.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.5', 'perspectives', '{\n        Guild:       \"If we can prove it, we will say it. What someone did with their dispatch case is their own responsibility.\",\n        Directorate: \"Public attribution is the mechanism for accountability. We support it when the evidence supports us.\",\n        Network:     \"The city has a right to know who is operating in its districts. We are providing that record.\",\n        Ghost:       \"We do not publish what we know about other factions\' operations. That is a principle, not a preference.\",\n        Syndicate:   \"Attribution is leverage. The question is always: what is the information worth on the table versus in hand?\",\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.5', 'design_note', '\"Standard information-attribution PA. Restriction requires Fresh or Stale token — Expired excluded (too degraded to constitute usable attribution evidence). Token spent regardless of outcome. Threshold from token age (Fresh = 45, Stale = 30) + Network +10. Ghost portrait −2: attributing any faction\'s covert op violates Ghost\'s belief that operational anonymity protects the intelligence discipline of the whole table — the highest negative portrait value in the set. Taxonomy: Shift/StandingMarker — the attribution is the delivery mechanism for the PS swing, not separate value.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.5', 'arbiter_note', '\"At Art 03 §9.2.0: Intel token placed on PA card with Target Profile face-down. At Art 03 §9.4.3.1.1: flip Target Profile face-up; verify token age — Fresh or Stale satisfies restriction; Expired does not. Beat 4: threshold = 30 base (Stale) + 15 if Fresh + 10 if Network. On success: announce \'[Acting faction] attributes [op type, quarter] to [target faction].\' Target −2 PS, acting +2 PS. Token spent. On fail: acting −1 PS. Token spent regardless.\"', '04___Card_System___Part2_Standard.md');
