INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.6', 'failcrit', 'faction(acting).standing.remove(2)', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.6', 'portrait', '{\n        Syndicate: PortraitEntry(submitter=+1),\n        Guild:     PortraitEntry(submitter=-1),\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.6', 'ps_framing', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.6', 'narrative', '\"Economic pressure in New Meridian is always visible. The faction applying it accepts that visibility as part of the cost.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.6', 'perspectives', '{\n        Guild:       \"Economic weapons undermine the table\'s capacity to build. We use them only when other options are exhausted.\",\n        Directorate: \"Sanctions are a formal instrument of institutional pressure. Applied correctly, they do not require apology.\",\n        Network:     \"We note who imposes economic sanctions on whom. The city will form its own judgment.\",\n        Ghost:       \"Public economic aggression makes enemies. We observe the transaction and its aftermath.\",\n        Syndicate:   \"Capital discipline is a legitimate instrument. The target chose to be in a position where this was possible.\",\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.6', 'design_note', '\"PS reversed by design: acting −1 (aggressor optic), target +1 (sympathy) on success. Value is purely resource denial (target loses up to 2 native; floor = 0 — remove all available if fewer than 2). Faction differentiation: Ghost plays freely (PS-agnostic), Network avoids (PS-dependent), Syndicate primary user (+15 threshold). Guild −1 portrait: economic weapons conflict with permanence-through-building doctrine.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.6', 'arbiter_note', '\"Beat 4. d100 vs threshold 40 (+15 Syndicate; doctrine_mod Neighbor +10 / Opposed −10). On success: remove 2 native resources from target, or all available if fewer than 2 (floor = 0); acting −1 PS; target +1 PS. On fail: acting −1 PS only. On failcrit: acting −2 PS.\"', '04___Card_System___Part2_Standard.md');
