INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.7', 'portrait', '{\n        Directorate: PortraitEntry(submitter=+1),\n        Network:     PortraitEntry(submitter=+1),\n        Ghost:       PortraitEntry(submitter=-1),\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.7', 'ps_framing', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.7', 'narrative', '\"Presence without voice is presence waiting to become something else.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.7', 'perspectives', '{\n        Guild:       \"We speak through what we build. But occasionally, we also speak.\",\n        Directorate: \"A formal address in a district we operate in is institutional communication. It is expected.\",\n        Network:     \"This is what we do. The address is the point.\",\n        Ghost:       \"Public addresses are signals. We note the frequency, the district, and the audience.\",\n        Syndicate:   \"Standing is a resource. We invest in it when the return is clear.\",\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.7', 'design_note', '\"Self-directed PS building — the missing card type in the standard set. STD.PA.4 attacks opponent PS; STD.PA.7 builds own. Automatic, 1 native, +2 PS. Presence requirement: cannot claim standing in districts where you have no legitimacy. Directorate +1 and Network +1: institutional communication and broadcasting are doctrinal for both. Ghost −1: public address = attention = exposure risk.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.7', 'arbiter_note', '\"Beat 4. Restriction at Beat 0: acting faction must have at least 1 presence token in declared district. If restriction fails, PA voided. On success: acting faction +2 PS.\"', '04___Card_System___Part2_Standard.md');
