INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.8', 'portrait', '{\n        Directorate: PortraitEntry(submitter=+1),\n        Ghost:       PortraitEntry(submitter=-1),\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.8', 'ps_framing', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.8', 'narrative', '\"The Table exists to make agreements. This is one of the few acts that uses it as intended.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.8', 'perspectives', '{\n        Guild:       \"We make agreements when they serve what we are building. We honor them for the same reason.\",\n        Directorate: \"A formal accord is the institutional mechanism for bilateral stability. We prefer it to informal arrangements.\",\n        Network:     \"Every formal agreement is a piece of the city\'s record. We observe the terms and what follows.\",\n        Ghost:       \"Accords create obligations. We are not opposed to what they achieve — only to what they commit us to.\",\n        Syndicate:   \"Every accord is an asset. The question is who controls the terms and what the exit costs.\",\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.8', 'design_note', '\"Accord initiation PA. Cost = 1 native flat (all factions). PA slot is the primary gate: 3 PA slots per Quarter, card is draw-dependent. PS vote at decline gates proposal quality (unreasonable proposal = proposer −1 PS). Blank form is a proposal, not a contract; 1 native signals that diplomacy is accessible. Ghost −1: Accords are commitments.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.8', 'arbiter_note', '\"Phase B: target faction named publicly. Beat 4: deliver blank AccordForm from ARBITER tableau supply to submitting faction. No timing constraint on drafting or placement — form queued for next Debrief when placed in Accord Placement Area. At Debrief: target reviews, accepts or declines per Art 06 §9.4. PS consequences per Art 06 §9.4.\"', '04___Card_System___Part2_Standard.md');
