INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.9', 'portrait', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.9', 'ps_framing', 'None', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.9', 'narrative', '\"New Meridian doesn\'t run on declarations alone. Sometimes a faction just needs to stand in the same room again, in front of the same people, and let them see it hasn\'t left.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.9', 'perspectives', '{\n        Guild:       \"We don\'t need a stage. We need people to see what we\'re already building here and decide to stay and watch.\",\n        Directorate: \"A scheduled forum, properly noticed. Continuity means showing up even in districts where we have little else to offer.\",\n        Network:     \"We don\'t stop talking to the people who live here just because the story\'s slow this month. That\'s the whole point of what we do.\",\n        Ghost:       \"We would rather listen than be listened to. Someone still has to stand in the room. This time, it\'s us.\",\n        Syndicate:   \"Cheap, and it buys another quarter of relevance somewhere we already paid to be.\",\n    }', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.9', 'design_note', '\"The Floor Act. Guarantees availability, not success — d100/50, no ring_mod/doctrine_mod, weakest reliable play by design (Pillar 4.8b). Restricted to a district carrying the acting faction\'s own deployment marker, below Established — reinforces a committed toehold, cannot open new territory. Cost = 1 native, matches passive generation exactly (Pillar 4.8d). Faction-agnostic: no affinity, no doctrine_mod, no portrait. Crit tail only: successcrit/failcrit ±1 PS (acting only); base success/fail carry no PS shift, keeping the floor non-punishing on an ordinary roll.\"', '04___Card_System___Part2_Standard.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.PA.9', 'arbiter_note', 'None', '04___Card_System___Part2_Standard.md');
