INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.1', 'design_note', '\"Outcome addition modifier: attaches Accord initiation as additional Beat 4 outcome on any PA. \"\n                   \"Fires on any host PA outcome — success or fail. Earned from STD.CA.9 success; free to assign. \"\n                   \"Cannot assign to STD.PA.8 or GUI.PA.2 (duplicate AccordForm). \"\n                   \"Must be held to a subsequent Month: Overture delivered at Beat 3 via STD.CA.9; host PA declared at Phase B before Beat 3. \"\n                   \"Target faction not declared at Phase B — named on AccordForm when drafted. \"\n                   \"assigned_pa is set when the faction attaches this card to a PA at Phase B — mirrors GD-01\'s fill-in-field pattern (deed.district), just faction-written instead of ARBITER-written.\"', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.1', 'arbiter_note', '\"On host PA resolution at Beat 4: deliver one blank AccordForm from ARBITER tableau supply to acting faction. \"\n                   \"Faction drafts and places in Accord Placement Area at their discretion — no timing constraint. \"\n                   \"Proceed per Art 06 §9.4.\"', '04___Card_System___Part3_Ring_Modifiers.md');
