INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.101', 'design_note', '\"Mirrors GHO.MOD.2 Perimeter Sensors\' Intel Token delivery template. Reward changed from an initial \'draw 1 modifier card\' (circular — a modifier card\'s reward shouldn\'t itself be another modifier card, with no thematic tie to \'overheard information\') — Intel Token on the triggering faction ties the reward to what the card is actually about.\"', '04___Card_System___Part3_Ring_Modifiers.md');
