INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.102', 'design_note', '\"Not ring-scoped by design — Accords have no ring dimension, so \'Core flavor\' comes from doctrine/theme (institutional paperwork), not a mechanical filter. Ring ModReact triggers don\'t require ring-scoping.\"', '04___Card_System___Part3_Ring_Modifiers.md');
