INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.103', 'narrative', '\"Core\'s review process exists to slow things down. It works exactly as designed, on whoever it\'s aimed at.\"', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.103', 'perspectives', 'None', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.103', 'design_note', '\"Hinders the flagged PA (−5 threshold — makes success harder), not a self-benefit. `arbiter.modify(target, field, delta)` is a new mutation form, not yet in confirmed vocabulary; flagged for reconciliation. Procedurally grounded in the existing BM-xx/M-11 threshold-modifier-accumulation pipeline (Art 03 §9.4.1.1/§9.4.3.1.3), not new ARBITER behavior.\"', '04___Card_System___Part3_Ring_Modifiers.md');
