INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.106', 'narrative', '\"Losing a foothold in Core isn\'t the end — there\'s always a contingency line item for exactly this.\"', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.106', 'perspectives', 'None', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.106', 'design_note', '\"Distinct from the existing Floor Act mechanic (PM02 VE-01) — this is a Core-specific, presence-loss-triggered reserve, not a general insufficient-resource safety net. NativeResource(holder) keys to the holder\'s own faction, not a rival\'s.\"', '04___Card_System___Part3_Ring_Modifiers.md');
