INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.107', 'narrative', '\"Standing shifts in Core get logged, cross-referenced, and answered — Core doesn\'t let a change go unremarked.\"', '04___Card_System___Part3_Ring_Modifiers.md');
