INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.107', 'design_note', '\"Straightforward capitalize-on-rival\'s-gain template — `faction(holder).standing.add(1)` stands on its own precedent within the Ring set, STD.MOD.102.\"', '04___Card_System___Part3_Ring_Modifiers.md');
