INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.108', 'narrative', '\"Core keeps records of every dispute. A district turning contested opens the door to citing precedent from somewhere else.\"', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.108', 'perspectives', 'None', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.108', 'design_note', '\"Reframed from an earlier seed concept (originally \'an Accord involving a Core-based faction forms\') — Accords aren\'t ring-scoped, so a Core-specific version couldn\'t distinguish itself from the other rings\' copies. Tension Marker placement is a genuinely ring-scoped, confirmed-vocabulary substitute with the same \'formal/procedural response\' character.\"', '04___Card_System___Part3_Ring_Modifiers.md');
