INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('STD.MOD.126', 'design_note', '\"Not ring-scoped, same as STD.MOD.102/STD.MOD.114 (Accords have no ring dimension) — Baryo flavor comes from doctrine (informal/unfiled agreements), not a mechanical filter. `accord.corrupted` rather than `.removed` — Baryo\'s version of the unscoped card reacts to terms being falsified, not a formal breach.\"', '04___Card_System___Part3_Ring_Modifiers.md');
