INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.4', 'portrait', '{Guild: PortraitEntry(submitter=+1)}', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.4', 'narrative', '\"The Guild does not always wait for permission.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.4', 'perspectives', '{\n        Guild:    \"Sometimes the crews arrive before the paperwork. This is not an accident.\",\n        Network:  \"We know this method. Presence before permission is how this city was actually built.\",\n        Ghost:    \"Establishing presence before authorization is requested — the Guild is better at covert operations than they admit.\",\n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.4', 'design_note', '\"Cost reasoning: 2 Capacity + 1 Findings (Mid-tier). Findings identify the un-zoned loopholes necessary to bypass prerequisites and break ground immediately.\"', '04___Card_System___Part4a_Guild.md');
