INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.5', 'narrative', '\"The Guild built New Meridian\'s infrastructure. Drawing from it is not theft. It is dividend.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.5', 'perspectives', '{\n        Guild:       \"We built this. Every unit we draw from it was always ours.\",\n        Syndicate:   \"The Guild built the pipes. They are billing us for the water. We respect the position even if we resent the rate.\",\n        Directorate: \"Infrastructure built under city contract belongs to New Meridian, not to the builder. We have the original agreements.\",\n    }', '04___Card_System___Part4a_Guild.md');
