INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.6', 'narrative', '\"In New Meridian, every foundation poured is a Guild invoice.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.6', 'perspectives', '{\n        Guild:       \"We do not ask to be compensated. We ensure that we are.\",\n        Directorate: \"The Guild has found a way to treat infrastructure development as a private revenue stream. This requires a regulatory response.\",\n        Network:     \"Every build is a Guild fee. Every fee is a constraint. The city grows on Guild\'s terms.\",\n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.6', 'design_note', '\"Construction analogue to GUI.CA.2 Materials Acquisition. Together with GUI.CA.2: no faction demolishes or builds in New Meridian without Guild being paid. Trigger is STD.CA.1 only — Labor Contract is a financial claim on physical construction, not influence or presence activity. Payout mirrors STD.CA.1.cost (2 Capacity). First qualifying STD.CA.1 from named faction only.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.6', 'arbiter_note', '\"At Beat 3: confirm whether named faction completed STD.CA.1 this Quarter. First qualifying play only. If triggered: deliver 2 Capacity to Guild\'s Dispatch Case.\"', '04___Card_System___Part4a_Guild.md');
