INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.7', 'ps_framing', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.7', 'narrative', '\"The offer was generous. The offer was also not optional.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.7', 'perspectives', '{\n        Guild:       \"We paid. That is more than most factions bother to do before taking what they want.\",\n        Directorate: \"Compensation before displacement is due process, however coercive the outcome. We would call this compliant.\",  \n        Ghost:       \"They didn\'t need to know anything about who they were displacing. Money and force. That is not strategy. That is simply having more of both.\",  \n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.7', 'design_note', '\"Guild\'s territorial response gap filled. Coercive eviction via buyout — the district-native payment to the target is what keeps this legally clean rather than outright seizure. Restriction (target presence in target_district) is the gate — no presence, nothing to buy out.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.7', 'arbiter_note', 'None', '04___Card_System___Part4a_Guild.md');
