INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.8', 'ps_framing', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.8', 'narrative', '\"The building failed on three counts. Guild wrote the counts specifically to catch it.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.8', 'perspectives', '{\n        Guild:       \"The building didn\'t meet code. That the code was written specifically to catch it is a separate matter.\",\n        Directorate: \"A documented violation, a certified inspection, a lawful demolition order. We have no complaint with due process, regardless of who initiates it.\",  \n        Syndicate:   \"They destroyed a structure that had real value and walked away with nothing to show for it but a permit. We would have made an offer first.\",  \n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.8', 'design_note', '\"Bureaucratic demolition via zoning enforcement. Strictly blind resolution — no negotiation, no side payment, just a real complaint tested against the dice. Restriction (target structure in target_district) is the gate.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.8', 'arbiter_note', 'None', '04___Card_System___Part4a_Guild.md');
