INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.9', 'restriction', '(\n        target_ca in game.dispatch.guild.beat3                       \n        and target_ca.restriction(district=target_district) == True  \n    )', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.9', 'cost', 'Capacity * 2\n         + district.target_district.native * 1', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.9', 'success', '(\n        target_ca.resolve(district=target_ca.target_district, outcome=success_and_successcrit),\n        target_ca.resolve(district=target_district,           outcome=success_and_successcrit),\n        \n    )', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.9', 'successcrit', 'None', '04___Card_System___Part4a_Guild.md');
