INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.9', 'portrait', '{Guild: PortraitEntry(submitter=+1)}', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.9', 'narrative', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.9', 'perspectives', '{\n        Guild:       \"Both sites are committed. The crews are already moving. The question was never whether — only where.\",\n        Directorate: \"The Guild has pre-authorized both sites through the same institutional channel. Efficient. We note the district selections.\",\n        Ghost:       \"Pre-committed construction at two sites simultaneously. We mark both districts as active before Beat 3 opens.\",\n        Network:     \"Guild\'s already decided. Whatever goes in the grid tonight, those two districts are getting built. We\'re watching which ones.\",\n        Syndicate:   \"Certainty commands a premium. Guild is paying it. The output justifies the cost — barely, but it does.\",\n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.9', 'design_note', '\"Construction certainty card. Target profile = {target_ca (named Guild Beat 3 d100 CA), target_district (district B)}. Beat 2 Automatic: registers guarantee. Beat 3: named CA resolves without roll — success+successcrit fires in CA\'s own district A AND in district B. Named CA\'s failcrit suppressed. Best target: GUI.CA.4 (success+crit = 2 presence + 1 structure per district; double-fire = 4 presence + 2 structures). CA.3 variant: 2 presence + 2 structures in two unclaimed districts. District B must satisfy the named CA\'s own restriction (checked at Beat 0). Total cost: this card (2C + 1 district native) + named CA cost + 2 dispatch slots.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.9', 'arbiter_note', '\"Phase B: Guild declares Works Guarantee with target profile = {CA-ID, district B}. Beat 0: (1) confirm named CA is Guild-submitted and d100; (2) confirm district B satisfies named CA\'s restriction (e.g., for CA.4: no existing Guild structure in district B; for CA.3: total presence in district B = 0). If either check fails: Works Guarantee void, cost returned. Beat 2: Works Guarantee resolves — record guarantee against named CA. Beat 3: named CA does NOT roll d100. Apply named CA\'s success+successcrit outcomes to district A (CA\'s declared target), then apply the same success+successcrit outcomes to district B. Named CA\'s failcrit consequences (Intel Tokens, resource transfers) are suppressed.\"', '04___Card_System___Part4a_Guild.md');
