INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.10', 'design_note', '\"Delivers GD-01 Grant Deed (Art 04 §12b.2). Capacity + district-native cost creates a cross-resource commitment SYN.CA.8 Land Title lacks. Restriction (no Guild structure, not Chorus Node) parallels CA.4. Automatic — no roll, no fail. Multiple orders on same district permitted; cost-governed. Doctrinal distinction from SYN.CA.8: Guild establishes construction rights (crews arrive to build); Syndicate files ownership claim (extraction).\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.CA.10', 'arbiter_note', '\"Beat 3: take 1 blank Grant Deed (GD-01) from ARBITER tableau; write target district name in \'district\' field and Guild in \'holder\' field; place in Guild\'s Dispatch Case. Card moves to Guild\'s hand at Debrief.\"', '04___Card_System___Part4a_Guild.md');
