INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.1', 'restriction', '(\n        district(target1).faction(Guild).presence > 0 and\n        district(target2).faction(Guild).presence > 0 and\n        district(target1).faction(Guild).structure == 0 and\n        district(target2).faction(Guild).structure == 0\n    )', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.1', 'cost', 'Capacity * 2 + Capital * 1 + Mandate * 1', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.1', 'boost', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.1', 'success', '(\n        arbiter.place(structure_block, district=target1, faction=Guild, count=1),\n        arbiter.place(structure_block, district=target2, faction=Guild, count=1),\n        faction(Guild).standing.add(3),\n    )', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.1', 'successcrit', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.1', 'fail', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.1', 'failcrit', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.1', 'portrait', '{Guild: PortraitEntry(submitter=+2)}', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.1', 'ps_framing', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.1', 'narrative', '\"The Civic Works Mandate is Guild\'s strongest public statement: we are not here to compete. We are here to build what New Meridian requires.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.1', 'perspectives', '{\n        Guild:   \"This is the declaration. Two districts, simultaneous, public. This is what we came here to do.\",\n        Network: \"Two districts at once. When Guild commits at this scale, the announcement becomes the infrastructure. The public knows before the cement sets.\",  \n        Ghost:   \"Guild builds when we have not yet established whether what is being built belongs in the answer. The structures will outlast the certainty they were built on.\",  \n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.1', 'design_note', '\"Guild\'s prestige build PA. Cost reasoning: 2 Capacity + 1 Capital + 1 Mandate (Ceiling-tier). Capital secures the massive land footprint, while Mandate bypasses zoning laws to fast-track construction. Both-or-nothing: if either district fails restriction at Beat 0, full PA is voided. PS +3: highest single-card build reward. Portrait +2: double structure = doctrinal maximum. Counter: Directorate DIR.PA.1 Regulatory Override applied to either district beforehand raises presence-placement costs, potentially blocking prerequisite presence for this card.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.1', 'arbiter_note', '\"Phase B: two distinct districts named. Beat 0: both restrictions checked simultaneously. If either fails (no Guild presence, or existing structure), entire PA voided; 4 Capacity returned; Guild takes Public Pass. Beat 4: place 1 structure in each declared district; Guild +3 PS.\"', '04___Card_System___Part4a_Guild.md');
