INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.2', 'success', '(\n        faction(target).resource(native).add(2),  \n        arbiter.deliver(Guild, AccordForm(blank)),  \n    )', '04___Card_System___Part4a_Guild.md');
