INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.2', 'portrait', '{Guild: PortraitEntry(submitter=+1)}', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.2', 'ps_framing', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.2', 'narrative', '\"Guild does not give resources away. The Infrastructure Bond is an investment — the terms make that clear.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.2', 'perspectives', '{\n        Guild:       \"We extend this partnership because the infrastructure serves both of us. The terms reflect that.\",\n        Directorate: \"Guild formalizes the relationship before the need becomes urgent. The Accord terms are what the investment was always going to require. This is how structural partners communicate.\",  \n        Syndicate:   \"Guild packages the extraction as partnership. The initial delivery is cover. The recurring return is the structure. We recognize this.\",  \n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.2', 'design_note', '\"Guild economic relationship PA. Cost: 1 Capacity (form price, per L200/L201) + 2 native delivered to target (sweetener — makes Accord terms credible). Accord on acceptance includes 1 Capacity/Upkeep income from target; net positive for Guild in 2+ Quarters. Restriction: Guild must have Established adjacent to target\'s operations. Distinct from STD.CA.9 Fund (Capital, covert, two-action route). Distinct from STD.PA.8 (bare form, no sweetener).\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.2', 'arbiter_note', '\"Phase B: target faction named publicly. Beat 4: deliver 2 native resources to target immediately; deliver blank AccordForm from ARBITER tableau supply to Guild. No timing constraint on drafting or placement — form queued for next Debrief when placed in Accord Placement Area. At Debrief: target reviews, accepts or declines per Art 06 §9.4. PS consequences per Art 06 §9.4. On accept: track Accord income (target pays Guild 1 Capacity at each Upkeep Step 6 while Accord active).\"', '04___Card_System___Part4a_Guild.md');
