INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.3', 'persistence_effect', 'game.board_condition(\n        scope  = district(target_district),\n        effect = on(structure_block.removed(faction=Any, district=target_district)):\n                     if district(target_district).faction(trigger.faction).presence > 0:  \n                         arbiter.place(structure_block, district=target_district, faction=trigger.faction, count=1),\n    )', '04___Card_System___Part4a_Guild.md');
