INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.3', 'ps_framing', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.3', 'narrative', '\"The plaque went up before the paint dried. Some things, this district decided, don\'t come down.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.3', 'perspectives', '{\n        Guild:     \"Some buildings matter more than what could replace them. We are simply the faction willing to say so in writing.\",\n        Network:   \"A public registry, a public commitment, a public consequence if it\'s violated. We have no objection to protection that happens in the open.\",  \n        Syndicate: \"They froze an asset that might have been worth more redeveloped. Heritage is a nice word for a building nobody\'s allowed to improve.\",  \n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.3', 'design_note', '\"Defense scaling gap addressed. Faction-agnostic — protects whichever structure in target_district is removed first, not just Guild\'s own. Absent-tier exclusion (GR 8.2b) is a card-side guard, not a HARD-rule override.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.3', 'arbiter_note', 'None', '04___Card_System___Part4a_Guild.md');
