INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.4', 'narrative', '\"The ribbon gets cut in front of a crowd assembled specifically to be impressed.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.4', 'perspectives', '{\n        Guild:       \"We built it. We are allowed to say so, loudly, in front of everyone who doubted it would get built at all.\",\n        Directorate: \"A public ceremony, a documented structure count, a public credibility gain. This is exactly how legitimacy should be earned.\",  \n        Ghost:       \"They announced exactly how much they\'ve built, in exactly which district, to everyone in the city at once. That is not celebration. That is a target list.\",  \n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.4', 'design_note', '\"Standing / PS Compounding gap filled. Broadcasting the ribbon-cutting to the city is the Exposure cost\'s role — the bigger the built footprint, the bigger the public event and the bigger the PS gain.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.4', 'arbiter_note', 'None', '04___Card_System___Part4a_Guild.md');
