INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.5', 'narrative', '\"The limitation was never structural. It was just expensive to remove.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.5', 'perspectives', '{\n        Guild:       \"The limitation was never structural. It was just expensive to remove.\",\n        Syndicate:   \"Every rule has a price. We respect a faction willing to find out what this one costs.\",  \n        Directorate: \"An exemption purchased rather than earned undermines the entire premise of zoning. This is not governance. This is a loophole with legal letterhead.\",  \n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.5', 'design_note', '\"Ceiling-tier expansion enabler. Finding the bureaucratic loophole and buying the necessary judges to skip the physical expansion limits, for the remainder of the Quarter.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.5', 'arbiter_note', 'None', '04___Card_System___Part4a_Guild.md');
