INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.6', 'narrative', '\"We didn\'t lose the structure. We sold it, for more than it cost to build.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.6', 'perspectives', '{\n        Guild:       \"We didn\'t lose the structure. We sold it, for more than it cost to build.\",\n        Syndicate:   \"A structure for their currency, priced at a premium. This is the cleanest transaction we\'ve seen out of Guild yet.\",  \n        Directorate: \"Strengthening a rival\'s footprint for a one-time payment is not strategy. It\'s a fire sale with better branding.\",  \n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.6', 'design_note', '\"A powerful, legal asset flip. Leverages existing footprint to extract deep foreign resource pockets. Restriction (Guild structure + target presence in target_district) makes this a negotiated transfer, not a handout.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.6', 'arbiter_note', 'None', '04___Card_System___Part4a_Guild.md');
