INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.7', 'narrative', '\"A permit doesn\'t build anything. It just stops anyone from asking why the building\'s already there.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.7', 'perspectives', '{\n        Guild:       \"We already have a foothold. The petition just makes what\'s obviously true, official.\",\n        Directorate: \"A documented petition, publicly filed, publicly granted. This is exactly how expansion should work — nothing invented, nothing improvised.\",  \n        Syndicate:   \"They filed paperwork to get something we would have simply bought. Cheaper, and nobody has to explain it to a committee.\",  \n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.7', 'design_note', '\"Requires existing foothold (restriction, not cost, is the gate). A blunt-force legal maneuver to crack an opponent\'s Established status in a single move.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.7', 'arbiter_note', 'None', '04___Card_System___Part4a_Guild.md');
