INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.8', 'narrative', '\"The plaque credits the subsidy program. It does not credit whoever actually paid for the concrete.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.8', 'perspectives', '{\n        Guild:     \"Every foundation poured in this district makes our case for us, whether or not we\'re the ones who poured it.\",\n        Network:   \"Development is newsworthy regardless of who\'s building. We have no complaint with a standing arrangement that just makes that visible.\",  \n        Syndicate: \"We pay for the concrete. They collect the credit. That is not a subsidy. That is a toll booth we didn\'t agree to.\",  \n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.8', 'design_note', '\"A standing effect. Guild weaponizes other factions\' construction efforts to build their own prestige. Seasonal, not Permanent — clears naturally at Quarter end rather than compounding indefinitely.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.8', 'arbiter_note', 'None', '04___Card_System___Part4a_Guild.md');
