INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.9', 'restriction', 'count(d in ([district(target)] + district(target).adjacent)\n                        where d.faction(Guild).structure > 0) >= 1', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.9', 'cost', 'Capacity * 3\n         + Capital  * 1\n         + Exposure * 1\n         + Mandate  * 1', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.9', 'boost', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.9', 'success', 'faction(Guild).standing.add(\n                  count(d in ([district(target)] + district(target).adjacent)\n                        where d.faction(Guild).structure > 0))', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.9', 'successcrit', '[faction(Guild).resource(d.native).add(1)\n                   for d in ([district(target)] + district(target).adjacent)\n                   if d.faction(Guild).structure > 0]', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.9', 'fail', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.9', 'failcrit', 'faction(Guild).standing.remove(\n                   count(d in ([district(target)] + district(target).adjacent)\n                         where d.faction(Guild).structure > 0))', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.9', 'portrait', '{Guild: PortraitEntry(submitter=+2)}', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.9', 'ps_framing', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.9', 'narrative', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.9', 'perspectives', '{\n        Guild:       \"The survey is not a campaign. It is a count. The city has been watching us build for years. Now they see the total.\",\n        Network:     \"Guild puts the ledger on the table. No spin, no campaign — just the number. Occasionally the number is the signal.\",\n        Ghost:       \"Quantified construction output translates to community dependency. The city\'s response is structural, not emotional. The leverage is already embedded in the districts.\",\n        Directorate: \"A public record of physical presence submitted to general attention. We maintain our own records. Guild\'s version of the total is, predictably, generous.\",\n        Syndicate:   \"Standing built on structures doesn\'t decay with the news cycle. Guild has been building this position for years. The ledger just makes it legible.\",\n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.9', 'design_note', '\"Ceiling Standing card. N = count of districts in {target ∪ adjacent} where Guild holds a structure block; max 9 (target + 8 adjacencies for Research Institute, per Art 01 §6.5 adjacency map). Success = +N PS. Failcrit = −N PS: symmetric, bet big/fail big. Successcrit adds +1 district.native per qualifying district — heterogeneous resource harvest; each district pays its own native type. Cost: 3C (show of strength) + 1 Capital (broadcast) + 1 Exposure (public act) + 1 Mandate (record). Distinct from GUI.PA.4 Civic Unveiling (Automatic, single-district, shallow PS ceiling): PA.4 is floor; City Ledger is d100 ceiling gamble. N-lock at Beat 0: ARBITER counts and records qualifying districts before Beat 3–4 resolution.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.9', 'arbiter_note', '\"Phase B: Guild declares City Ledger and names target district publicly. Beat 0: identify qualifying set = {target district} + {all adjacent districts}; count Guild structure blocks across that set = N. If N = 0, PA voided, cost returned. Record N. Beat 4: d100 vs 40. Success: Guild +N PS. Successcrit (01–05): Guild +N PS AND for each qualifying district yield +1 of that district\'s native resource to Guild. Fail: no effect (cost sunk). Failcrit (96–00): Guild −N PS.\"', '04___Card_System___Part4a_Guild.md');
