INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.10', 'restriction', '(faction(Guild).structure_block.count(district(target)) == 0\n               and faction(target).structure_block.count(district(target)) == 0\n               and faction(Guild).presence_token.count(district(target)) > 0\n               and faction(target).presence_token.count(district(target)) > 0)', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.10', 'cost', 'Capacity * 2\n         + faction.target.native * 1', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.10', 'boost', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.10', 'success', '[arbiter.place(structure_block, district=target, faction=target, count=1),\n               faction(Guild).standing.add(2),\n               faction(target).standing.add(1)]', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.10', 'successcrit', '[arbiter.place(structure_block, district=target, faction=Guild, count=1),\n                   arbiter.place(presence_chip, district=target, faction=Guild, count=1)]', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.10', 'fail', 'None', '04___Card_System___Part4a_Guild.md');
