INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.10', 'ps_framing', '\"Public cooperation between Guild and allied faction is visible to New Meridian; Guild leads (+2 PS) as acting faction bearing roll risk; target faction participates (+1 PS).\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.10', 'narrative', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.10', 'perspectives', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.10', 'design_note', '\"Restriction (both Present, neither has structure) frames this as a first-infrastructure moment — neither party is entrenching, both are establishing. Success: target gets structure block. Successcrit: both factions get structure blocks simultaneously + Guild gains 1 Presence Token. Failcrit: both lose 1 Presence Token — failed public coordination is worse than no coordination. PS asymmetry (Guild +2, target +1) reflects risk differential, not hierarchy.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.PA.10', 'arbiter_note', 'None', '04___Card_System___Part4a_Guild.md');
