INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.MOD.1', 'design_note', '\"Guild\'s React presence card: when a Guild chip is removed from a district, Guild may immediately place a chip back. \\\"Established communities don\'t abandon positions — they return.\\\" The return is reflexive, not planned; no structure dependency, since structure may be removed simultaneously when chips hit 0 and the trigger window must not require it. cost=None reflects the reflexive framing — playtest-flagged, not a final balance call.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.MOD.1', 'arbiter_note', '\"On trigger (a Guild presence chip is removed from a district): Guild may immediately place one presence chip back in that same district, no cost. Resolves before the acting faction\'s turn continues.\"', '04___Card_System___Part4a_Guild.md');
