INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.MOD.7', 'design_note', '\"Scaling structural defense. If an opponent manages to remove a Guild structure, Guild burns Capacity to flood the district with 2 presence chips. The territory becomes completely infested with Guild influence, preventing the attacker from claiming the space they just cleared.\"', '04___Card_System___Part4a_Guild.md');
