INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.MOD.9', 'perspectives', '{\n        Guild:       \"Somebody\'s putting down roots. That means permits, inspections, code review. That means us.\",\n        Directorate: \"Guild\'s paperwork trail on every Established filing is, admittedly, more thorough than ours.\",\n        Ghost:       \"A structure-independent income trigger. Notable — Guild reads territory before it reads construction.\",\n        Network:     \"Guild\'s inspectors show up before our own press release does. Efficient, if a little presumptuous.\",\n        Syndicate:   \"A fee nobody negotiated and everybody pays. That\'s a business model we respect.\",\n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.MOD.9', 'design_note', '\"Fourth angle of Guild\'s passive-income quartet (MOD.2 build / MOD.8 demolish / MOD.9 settle / MOD.4 premium-rate variant). Fires on any opponent\'s Established Marker placement, citywide, no structure or presence requirement. Flat +1 Capacity, Automatic, Immediate. Distinct trigger object from MOD.2 (structure_block.placed) — no overlap or double-count risk even if a single covert op both adds presence past the Established threshold and places a structure in the same beat.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.MOD.9', 'arbiter_note', 'None', '04___Card_System___Part4a_Guild.md');
