INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.MOD.10', 'ps_framing', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.MOD.10', 'narrative', 'None', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.MOD.10', 'perspectives', '{\n        Guild:       \"We don\'t fight for the block. We decide who gets the scaffolding on time.\",\n        Directorate: \"An unlicensed thumb on the scale before the contest even opens. Noted, not actionable.\",\n        Ghost:       \"A public commitment with private timing risk. Guild bets on today\'s map holding through the Quarter.\",\n        Network:     \"Everyone can see who Guild backed. That\'s a story whether the bet pays off or not.\",\n        Syndicate:   \"Guild\'s monetizing uncertainty before the dice even get picked up. Professionally, we approve.\",\n    }', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.MOD.10', 'design_note', '\"First Guild card to influence Battlefield Strength (§10) without Guild itself contesting the district. New mechanical pattern: a Seasonal ModReactCard registers a delta against a named contesting faction\'s total, resolved later at §10.1.2 rather than played live like a ModBattleCard. Fizzle risk (named faction may no longer be contesting when §10 actually resolves) is the cost of early commitment and is the card\'s core narrative tension. Restriction requires Guild Present or adjacent in the district. Target is any Dominant faction — no doctrine_mod; Guild\'s construction contracts are transactional, not political. Requires new Art 03 §10.1.2 procedure step — see Outstanding Issues below. `persistence_clearing_trigger` is None — the card clears at Phase 21 (End of Quarter) regardless of outcome, the default Seasonal expiry already implied by `persistence`; no discrete clearing event exists for this card.\"', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GUI.MOD.10', 'arbiter_note', '\"On trigger (Tension Marker placed in any district): if Guild satisfies restriction, Guild may declare target_faction (must currently be Dominant/tied in the district) and direction (Support +2 / Withhold −2), and pay Capacity×1. ARBITER records the condition publicly against the district. At §10.1.1 (Identify Contesting Factions), if target_faction is among the identified contestants: apply the registered magnitude to target_faction\'s declared total at §10.1.2, alongside Battlefield Modifier Cards and Intel Tokens. If target_faction is not contesting: condition lapses, no effect, no refund. Condition clears automatically at Phase 21 if §10 does not resolve the district this Quarter. Procedure step formalization still open — see Outstanding Issues.\"', '04___Card_System___Part4a_Guild.md');
