INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.2', 'success', 'game.dispatch(faction(acting), IntelDeliverySlip(faction=faction(target), op_type=faction(target).op(beat=3).type, district=faction(target).op(beat=3).district))', '04___Card_System___Part4b_Ghost.md');
