INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.2', 'narrative', '\"To know what they are doing while they are doing it — that is the only intelligence that matters.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.2', 'perspectives', '{Ghost: \"We do not wait for the after-action report. We read the operation as it happens.\"}', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.2', 'arbiter_note', '\"Crit success: deliver IntelToken (faction=target) to acting faction\'s case. Success: write target faction\'s first submitted op type and district on Intel Delivery Slip; deliver to acting faction\'s case. Fail: deliver Notification Slip to target faction\'s case. Crit fail: apply PS −2.\"', '04___Card_System___Part4b_Ghost.md');
