INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.3', 'portrait', '{Ghost: PortraitEntry(submitter=+1)}', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.3', 'narrative', '\"Understanding the operation before it begins. That is the only tactical advantage worth having.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.3', 'perspectives', '{Ghost: \"We did not take their cards. We simply read their intentions. They will act on plans we already know.\"}', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.3', 'design_note', '\"SIGINT tap model: Ghost taps faction X\'s dispatch channel at Beat 2. ARBITER reads faction X\'s Beat 3 grid column at Beat 2 resolution (name + declared target only; modifier cards excluded). IntelDeliverySlip delivered to Ghost at Beat 2 resolution. Beat 2 commitment is the risk. Empty case = empty slip — resources spent. DR-xx (DispatchReport) collapsed into IS-xx — column read is IntelDeliverySlip with list content.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.3', 'arbiter_note', '\"During Beat 2 resolution of this card: read faction X\'s Beat 3 resolution grid column. Write an IntelDeliverySlip listing each operation by name and declared target (district, faction, or object). Modifier cards not included. Deliver privately to Ghost at Beat 2 resolution. Do not notify faction X. If faction X has no Beat 3 operations, deliver an empty slip — Ghost\'s resources are spent. Procedure pending Art 03 Beat 2 addition.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.3', 'value_rating', '1', '04___Card_System___Part4b_Ghost.md');
