INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.5', 'narrative', '\"Ghost has been considering what the record says. It is never quite right.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.5', 'perspectives', '{Ghost: \"The attribution is wrong. Systematically, deliberately wrong. By the time anyone checks, it will have been wrong for a while.\"}', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.5', 'design_note', '\"Fills Information|Corrupt|IntelToken at the offensive targeting scope: alters faction attribution on a token publicly placed on an active PA. Distinct from GHO.CA.12 Source Substitution (which re-keys Ghost\'s own held tokens). L222 compliant — targets publicly placed tokens in FRG only (Beat 0–4 window). target_freeform carries the replacement faction name declared at §9.1.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.5', 'arbiter_note', '\"At Beat 3: check whether target faction has any Intel Token submitted on an active PA in the Faction Resolution Grid. If yes: alter the faction_name field on that token to the faction named in target_freeform. Token remains face-down on the PA; target faction is not notified. If no qualifying token: card fizzles, 1 Findings spent, no effect.\"', '04___Card_System___Part4b_Ghost.md');
