INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.7', 'narrative', '\"Every asset leaves a signal. Ghost listens until the signal becomes a pattern.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.7', 'perspectives', '{Ghost: \"A station does not move. It waits until the target walks past it again.\"}', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.7', 'design_note', '\"Ghost\'s dedicated gather platform. Higher yield than STD.CA.5 (2 tokens vs 1 on success) at double Findings cost. Threshold 55 calibrated above STD.CA.5 base (50) — Station is a reliable sustained platform. Adjacency restriction: deployed node requires Ghost presence in target district or adjacent. Cards stack: STD.CA.5 and Station may both target same faction in same Quarter.\"', '04___Card_System___Part4b_Ghost.md');
