INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.8', 'narrative', '\"Some intelligence is gathered patiently. Some is taken all at once.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.8', 'perspectives', '{Ghost: \"The take was complete. Everything they transmitted this Quarter. We have it.\"}', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.8', 'design_note', '\"Singleton. Variable cost via boost: base 1 Findings, each boost unit +1 Findings (no declaration — ARBITER infers n_boost from total submitted at Beat 0, per the confirmed boost mechanic); success = 2×(1+n_boost) Intel tokens; crit success = 3×(1+n_boost). Fail = nothing. Threshold 40 confirmed, does not scale with boost — variable cost and fail=nothing are sufficient risk; low threshold is the compensating upside. Adjacency restriction applies (Ghost presence in target district or adjacent). Intel holding guideline is 4 (not HARD); high-boost plays may exceed guideline.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.8', 'arbiter_note', '\"At Beat 0: validate base cost paid; n_boost = excess payment ÷ 1 Findings; place n_boost BM-xx on grid slot; lock success/successcrit magnitudes using (1+n_boost). At Beat 3: success = dispatch 2×(1+n_boost) IntelToken(faction=target) to Ghost\'s case; crit success = dispatch an additional (1+n_boost) (3×(1+n_boost) total); fail = nothing; crit fail = NotificationSlip to target; remove BM-xx to supply.\"', '04___Card_System___Part4b_Ghost.md');
