INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.15', 'ps_framing', 'None', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.15', 'narrative', '\"The paperwork always ships. Nobody checks that it still says what it said when it left the building.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.15', 'perspectives', '{\n        Ghost:       \"We did not guess. We read enough to know where they were going before they did.\",\n        Directorate: \"Redirection without disruption is the mark of real institutional competence. We would call it enforcement. Ghost calls it business.\",  \n        Network:     \"Someone rewrote the terms of an operation and no one at that table ever knew. That is exactly the kind of decision that should never be made in silence.\",  \n    }', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.15', 'design_note', '\"Beat 2 positional wager against a Beat 3 operation Ghost hasn\'t seen yet. The Intel Token requirement (about target faction, Fresh/Stale) grounds the guess in real intelligence rather than a coin flip. Ghost\'s guess is written using the same Target Profile field as any other targeting declaration — target_district carries the expected district directly, no separate field-name declaration needed. Scoped to district-guessing only; object-guessing needs target_object\'s type-vs-instance semantics resolved first (see Outstanding Issues). A miss is \'no effect, cost spent\' — the fizzle is silent, Ghost\'s op simply produces nothing.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.15', 'arbiter_note', '\"At Covert Dispatch, Ghost submits its own Target Profile with target_faction set to the opponent and target_district set to the district it\'s betting the opponent\'s first Beat 3 operation will name; target_freeform carries the replacement district. At Beat 3, before the target\'s first-submitted operation resolves, ARBITER compares Ghost\'s declared target_district against that same field on the target\'s operation. If they match, silently overwrite the target\'s target_district with Ghost\'s target_freeform value before resolution proceeds; if not, no action is taken and nothing is disclosed to either faction.\"', '04___Card_System___Part4b_Ghost.md');
