INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.9', 'narrative', '\"The structure count is the number of ways they have committed themselves. Ghost counts carefully.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.9', 'perspectives', '{Ghost: \"We do not need to be inside their operation. We need to know how large it is.\"}', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.9', 'design_note', '\"Converts held intelligence into future modifier capability — Ghost builds next Quarter\'s hand from this Quarter\'s intelligence. Pairs with Station, Full Take, and Synthesize: the SCIF pipeline is the destination for accumulated faction-keyed Intel. Yield scales with target development, creating an intelligence premium on heavily-built opponents.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.9', 'arbiter_note', 'None', '04___Card_System___Part4b_Ghost.md');
