INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.11', 'success', 'game.reveal_private(\n                    faction(target).classified_directive,\n                    to  = faction(acting),\n                    via = arbiter\n                  )', '04___Card_System___Part4b_Ghost.md');
