INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.11', 'portrait', '{Ghost: PortraitEntry(submitter=+1, modifier=+1, mod_where=game.outcome==Success)}', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.11', 'narrative', '\"The Directive is not a secret. It is a pattern. Ghost reads patterns.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.11', 'perspectives', '{Ghost: \"We are not guessing. We have read enough of their decisions to know what they are trying to protect.\"}', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.11', 'design_note', '\"Ghost\'s highest-cost card. Cost: 2 faction-keyed Intel tokens + 3 Findings, all physically present (Art 04 §5 P20). Threshold 30 — reserved for Ghost players who have built Intel reserves. No adjacency restriction (analytical work — consistent with GHO.CA.1-GHO.CA.5 pattern). Portrait: submitter=+1 unconditional + modifier=+1 on success. ClassifiedDirective component type pending verification in Art 02 series.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.11', 'arbiter_note', '\"Privately reveal target faction\'s Classified Directive to Ghost player across screen. Do not announce to table. Ghost may not publicly prove knowledge. Crit fail: NotificationSlip to target only — do not reveal what Ghost was attempting.\"', '04___Card_System___Part4b_Ghost.md');
