INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.6', 'narrative', '\"Raw surveillance is noise. What Ghost does to it — that is signal.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.6', 'perspectives', '{Ghost: \"We don\'t just gather. We process. The difference is what we are.\"}', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.6', 'design_note', '\"GATHER→SYNTHESIZE Double Case Pass combo (L145): Gather in Month 1, Synthesize in Month 2/3. Consumed token is any held token — not required to be faction-keyed. Generated tokens carry the consumed token\'s faction key — enables Gather→Synthesize→Flip pipeline for any target faction.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.6', 'arbiter_note', '\"Consume 1 held Intel token (any faction key) and 1 Findings from Ghost\'s supply. Deliver 3 Intel tokens keyed to the consumed token\'s faction to Ghost\'s Dispatch Case.\"', '04___Card_System___Part4b_Ghost.md');
