INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.12', 'narrative', '\"The record says what Ghost needs it to say.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.12', 'perspectives', '{Ghost: \"The attribution is wrong. It will stay wrong. What matters is what Ghost does with it next.\"}', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.12', 'design_note', '\"Re-keys an Intel token\'s faction field to faction(target). Quarter field unchanged — freshness carries over. Cost = CA slot (no Findings). Automatic — no dice, no risk. Token is target_object: submitted in case alongside card, returned after alteration. A Standard-deck card carries an equivalent mechanic.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.12', 'arbiter_note', '\"Token submitted in Ghost\'s case alongside card. At Beat 3: alter faction_name field on token to faction(target); return altered token to Ghost\'s case. No announcement.\"', '04___Card_System___Part4b_Ghost.md');
