INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.13', 'success', 'arbiter.dispatch(faction(acting), PhantomRecord(\n        target_faction = faction(named_opponent),\n        district        = target_district,\n        generation_snapshot = game.resource_generation(faction=named_opponent, district=target_district),\n    ))', '04___Card_System___Part4b_Ghost.md');
