INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.13', 'ps_framing', 'None', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.13', 'narrative', '\"Every ledger has a shadow. Ghost simply keeps the other copy.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.13', 'perspectives', '{\n        Ghost:     \"We are not touching their accounts. We are keeping our own copy of what they earn.\",\n        Syndicate: \"Every income stream is a resource waiting to be captured twice. We admire the elegance, even if we would have found a subtler way to bill for it.\",  \n        Guild:     \"They built nothing. They copied our ledger and called it income. That is not enterprise. That is theft with better paperwork.\",  \n    }', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.13', 'design_note', '\"A financial twin to SCIF. Instead of generating Modifier cards off structural density, this converts Findings into a mirrored payout of the target\'s passive district income. Restriction (target presence in target_district) is the gate — no presence, nothing to mirror.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.13', 'arbiter_note', '\"At Beat 3 on success: complete a DA-02 PhantomRecord per Art 04 §12a.3 (quarter, target_faction, district, generation_snapshot) and place it in Ghost\'s Dispatch Case. Debrief procedure for DA-02 slips is defined in Art 04 §12a.3 — not redefined here.\"', '04___Card_System___Part4b_Ghost.md');
