INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.14', 'ps_framing', 'None', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.14', 'narrative', '\"Nothing was stolen. Nothing was broken. It simply never arrives.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.14', 'perspectives', '{\n        Ghost:     \"We do not need to know what it was. We only need to know it will not happen.\",\n        Syndicate: \"An operation that never happened costs nothing to explain. We respect efficiency, wherever it comes from.\",  \n        Network:   \"Something disappeared and no one will ever know what it was. That is not victory. That is erasure, and erasure is exactly what we exist to prevent.\",  \n    }', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.14', 'design_note', '\"Massive multi-resource cost to justify an unblockable, blind veto of an opponent\'s action. No restriction, no threshold — the cost alone is the gate.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.CA.14', 'arbiter_note', '\"At Beat 2: identify target_faction\'s first-submitted Beat 3 operation (same submission-order concept used for tiebreaking, Governing Rule 7.3b). Remove it from the resolution grid before Beat 3 begins. Target faction is not notified in advance.\"', '04___Card_System___Part4b_Ghost.md');
