INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.1', 'restriction', '(\n        faction(Ghost).holds_intel_token(faction=target1) and\n        faction(Ghost).holds_intel_token(faction=target2) and\n        target1 != target2\n    )', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.1', 'cost', '(\n        Findings * 2\n        + Exposure * 1\n        + faction(target1) * 1\n        + faction(target2) * 1\n        + IntelToken(about=faction(target1)) * 1\n        + IntelToken(about=faction(target2)) * 1\n    )', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.1', 'boost', 'None', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.1', 'success', '(\n        arbiter.announce(attribution=target1, context=intel_token_1.quarter),\n        arbiter.announce(attribution=target2, context=intel_token_2.quarter),\n        faction(target1).standing.remove(2),\n        faction(target2).standing.remove(2),\n        faction(Ghost).standing.add(2),\n    )', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.1', 'successcrit', 'None', '04___Card_System___Part4b_Ghost.md');
