INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.1', 'portrait', '{Ghost: PortraitEntry(submitter=+1)}', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.1', 'ps_framing', 'None', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.1', 'narrative', '\"Ghost does not publish because it wants credit. Ghost publishes because the analysis is complete and the disclosure serves more than the concealment.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.1', 'perspectives', '{\n        Ghost:       \"We have done the work. Both attributions are supported. The timing is correct. We publish.\",\n        Directorate: \"Ghost discloses both attributions from verified position. The timing was chosen. The evidence was held until both targets were confirmed. This is how intelligence should enter the record.\",  \n        Network:     \"Ghost waited for both confirmations. We published after the first. The second attribution was true by the time Ghost released it — and so was all the damage that came between.\",  \n    }', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.1', 'design_note', '\"Ghost\'s highest-cost PA. 2 Findings + 1 Exposure + 1 native from each named target + 2 Intel tokens (different factions) — Exposure and target-native components serve as a cross-resource gate matching the NET.CA.1-style \'trade dependency\' pattern. Automatic — token requirement is the certainty check (Ghost does not publish speculation). Simultaneous dual attribution: each target −2 PS, Ghost +2 PS flat. Portrait +1: calculated disclosure affirms \'understanding must precede action\' doctrine. Option 3 (operational blackout mechanic) flagged as PM05 item for potential Network PA extension. Taxonomy: Shift/StandingMarker — the attribution is the delivery mechanism for the PS swing, not separate value. Locked as an intentional Ghost doctrinal advantage: spending 2 already-earned, faction-specific tokens to land a double-attribution strike is exactly what Ghost\'s intel-accumulation-as-leverage doctrine should reward.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.1', 'arbiter_note', '\"Phase B: Ghost names two target factions. Both Intel tokens submitted with case. Beat 4: announce \'[Ghost] attributes [op type, quarter] to [target1]\' and \'[Ghost] attributes [op type, quarter] to [target2].\' Each target −2 PS. Ghost +2 PS. Both tokens spent.\"', '04___Card_System___Part4b_Ghost.md');
