INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.2', 'success', 'game.world_condition(\n        scope    = district(target),\n        target   = covert_op(faction=target_faction),\n        effect   = threshold.remove(15),\n        duration = Transient,  \n    )', '04___Card_System___Part4b_Ghost.md');
