INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.2', 'narrative', '\"Ghost does not need credit for this. The scrutiny is the point.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.2', 'perspectives', '{\n        Ghost:     \"We are not making an accusation. We are requesting that the process do what the process is designed to do.\",\n        Syndicate: \"Ghost asks ARBITER to enforce the review. No exposure, no escalation, no record beyond the request itself. We recognize the structure. The target carries the friction. Ghost carries nothing.\",  \n        Guild:     \"Ghost routes the pressure through ARBITER rather than holding the position itself. The district gets harder to operate in. Nothing is built. Ghost calls this strategy. Guild calls it avoidance.\",  \n    }', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.2', 'design_note', '\"Ghost operational pressure PA. Uses institutional scrutiny (ARBITER) to apply −15 threshold to target faction\'s covert ops in named district next Month. No PS gain for Ghost — the channel is a tool. Ghost adjacency: must have presence in district adjacent to target. Persistence = Transient: GHO.PA.2 card face-up on table + district marker until Close Month of next Month. Multiple P18s from different Months can stack. Distinct from GHO.PA.1 (attribution) — GHO.PA.2 creates ongoing pressure without disclosure.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.2', 'arbiter_note', '\"Beat 4: place GHO.PA.2 card face-up on table with marker on target district. Apply −15 threshold penalty to all covert operations submitted by target faction in target district next Month (Beat 3). Card expires Close Month that Month — announce removal, return card to Ghost. Multiple GHO.PA.2 cards on same district from different Months stack (each tracked independently). Ghost adjacency enforced at Beat 0.\"', '04___Card_System___Part4b_Ghost.md');
