INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.3', 'ps_framing', 'None', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.3', 'narrative', '\"Ghost does not release because it ran out of options. Ghost releases because it chose this moment, these records, and this account. The archive is not empty — this is a selection.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.3', 'perspectives', '{\n        Ghost:       \"The tokens are expired. The operations they document are closed. We are not losing intelligence by releasing this — we are spending it correctly.\",\n        Directorate: \"Ghost held these until the moment suited them. The records are verified. The disclosure is formal. This is how intelligence should enter the public domain.\",\n        Network:     \"Ghost sat on this for three Quarters and then picked their moment. We published when we had it. Ghost published when it helped Ghost.\",\n    }', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.3', 'design_note', '\"Base success = +1 PS; successcrit = +1 PS additional. Boost = expired Intel tokens (status=Expired, holder=Ghost); each submitted token = 1 BM-xx at Art 02 §9.4.3.1.0.0. BM-xx ×(1+n) multiplies all effects: n tokens → +(1+n) PS on success; +(1+n)+1 PS on successcrit (success + crit both multiplied); −(1+n) PS on failcrit. Restriction ensures at least 1 expired token present (narrative grounding). Faction Player may optionally narrate what records are being declassified — this is not a procedure step.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.PA.3', 'arbiter_note', '\"Phase B: Ghost declares expired tokens (status=Expired) being submitted as boost — record count as n. Beat 4 Art 03 §9.4.3.1.0.0: place n BM-xx on card; expired tokens deposited to Dossier at Art 02 §9.4.3.1.0.1. Art 03 §9.4.3.3: effects ×(1+n). Success: Ghost +(1+n) PS. Successcrit: Ghost +(1+n) PS success + +(1+n) PS crit delta = +(2+2n) PS total. Fail: no effect. Failcrit: Ghost −(1+n) PS.\"', '04___Card_System___Part4b_Ghost.md');
