INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.MOD.9', 'design_note', '\"Punishes brute-forcing a PA with Intel Tokens by stripping every Modifier card riding it — full-stack wipe, not just the submitter\'s. This is a bigger swing than most single-card React effects in the corpus, deliberately so.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.MOD.9', 'arbiter_note', '\"On trigger (a PA is submitted using an Intel Token as payment): confirm Ghost pays Findings(1). Remove every Modifier card currently attached to that PA, regardless of owner.\"', '04___Card_System___Part4b_Ghost.md');
