INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.MOD.10', 'design_note', '\"Hugely disruptive — clears the target\'s entire unplayed CA/PA hand; they redraw normally at Debrief. Intentional, not softened. Steepest cost in the fossil set (Findings(2) + IntelToken(1)) reflects the swing.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.MOD.10', 'arbiter_note', '\"On trigger (any faction submits a PA): confirm Ghost pays Findings(2) + IntelToken(1) and names the submitting faction as target. Target discards all unplayed Covert Operation and Public Act cards from hand; they redraw normally at next Debrief per standard draw procedure.\"', '04___Card_System___Part4b_Ghost.md');
