INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.MOD.11', 'design_note', '\"A public hijacking. The table sees Ghost swap the paperwork, but because Target Profiles are placed face-down, no one — not even the table — knows what Ghost changed the target to until Beat 4.\"', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('GHO.MOD.11', 'arbiter_note', '\"Reacts at Art 03 §9.2.0 when an opponent places a PA with a face-down Target Profile. Ghost announces the React, pays Findings(1) + Exposure(1), and declares a replacement Target Profile privately to ARBITER. ARBITER discards the opponent\'s original face-down Target Profile and places Ghost\'s declared_profile face-down in its place. At Beat 4 Apex Check, the PA resolves against Ghost\'s corrupted target.\"', '04___Card_System___Part4b_Ghost.md');
