INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.2', 'restriction', '(\n        district(target).faction(target).deployment_marker >= 1\n        AND intel(faction=faction(target), age_rounds<=1) >= 1\n        AND district(target) != ChorusNode.deployment_marker\n    )', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.2', 'cost', 'Mandate * 2 + Findings * 1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.2', 'success', 'game.move(faction(target).deployment_marker, from_=district(target), to=Directorate.tableau.detention, public=True)', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.2', 'successcrit', 'faction(acting).mandate.add(3)', '04___Card_System___Part4c_Directorate.md');
