INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.3', 'success', 'game.deliver(IntelDeliverySlip(district=district(target), content=\"op_type_only\", source=\"beat3_grid\"), to=faction(acting), private=True)', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.3', 'successcrit', 'None', '04___Card_System___Part4c_Directorate.md');
