INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.3', 'portrait', '{Directorate: PortraitEntry(submitter=+1)}', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.3', 'narrative', '\"The Directorate monitors because monitoring is their primary tool for managing what they cannot directly control.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.3', 'perspectives', '{Directorate: \"We know what moves through that district before it moves. We will respond accordingly.\"}', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.3', 'design_note', '\"Redesigned v2.0: original permanent passive feed with beat3_pre_resolution delivery invalidated — Governing Rule 7.2a prohibits covert board markers; ARBITER holds no log in L1. Episodic model: Directorate watches one district one month. ARBITER reads existing Beat 3 grid row at Beat 2 resolution — no new tracking. Op type only, no faction. Multiple copies in Directorate deck flagged for deck design pass.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.3', 'arbiter_note', '\"During Beat 2 resolution of this card: check the Beat 3 resolution grid for covert operations targeting district(target). For each operation present, write the operation type on an IntelDeliverySlip and deliver privately to Directorate. Do not include faction identity. If no Beat 3 operations target the district, deliver nothing — Directorate\'s resources are spent. Procedure pending Art 03 Beat 2 addition.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.3', 'value_rating', '2', '04___Card_System___Part4c_Directorate.md');
