INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.4', 'success', 'game.move(faction(acting).presence, count=2, from_=district(source), to=district(target))', '04___Card_System___Part4c_Directorate.md');
