INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.4', 'ps_framing', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.4', 'narrative', '\"One token, formally revoked. Everything else about the district stays exactly as it was — which is the point.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.4', 'perspectives', '{\n        Directorate: \"We don\'t demolish a position. We correct one entry and let the rest of the record stand.\",\n        Ghost:       \"No excess. A removal that doesn\'t pretend to be more than it is — we respect the discipline.\",  \n        Syndicate:   \"A foothold we spent months building, erased with one signature and filed as paperwork.\",  \n    }', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.4', 'design_note', '\"Redesigned (v2.0 → v3.0). ARBITER performs no comparison or tier calculation — removes exactly 1 named presence token from target faction in target district; the tier consequence (if any) is a natural downstream effect of fewer tokens under the standard influence-level rules, not a direct write. Established+ restriction preserved from original (one-time boolean gate, not a recurring calculation — compliant with GR 6.1 / Design Pillar 4.7b). Locked cost principle: this base version (N=1) is mono (Mandate×2). Any future variant removing N>1 tokens must use cross-resource cost. Distinct from DIR.CA.5 Sanctioned Raid: public/Automatic/no-roll vs. covert/d100/boost-scaled.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.4', 'arbiter_note', '\"Beat 4: confirm target faction holds Established+ tier in target district. Remove 1 presence token belonging to target faction from target district (target\'s choice of which physical chip, if multiple present).\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.5', 'id', '\"DIR.PA.5\"', '04___Card_System___Part4c_Directorate.md');
