INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.5', 'persistence_clearing_trigger', 'faction(Any).pays(  \n        [Resource(Mandate, 1), Resource(district(target).native, 1)],\n        to=Reservoir,\n    )', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.5', 'persistence_effect', 'game.board_condition(\n        scope  = district(target),\n        effect = on(presence_chip.placed(district=district(target))):\n                     arbiter.remove(trigger.chip, faction=trigger.faction, district=district(target), count=1),\n        \n        \n        \n        \n    )', '04___Card_System___Part4c_Directorate.md');
