INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.5', 'boost', 'True: Mandate * 1 + district.target_district.native * 1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.5', 'success', '[game.remove_modifier_cards(district(target_district), faction=faction(target)),\n                 game.remove(faction(target).presence_tokens, district(target_district), count=(1 + n_boost)),\n                 faction(acting).standing.remove(1 + n_boost)]', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.5', 'successcrit', 'faction(acting).standing.add(1 + n_boost)', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.5', 'fail', 'game.dispatch(faction(target), NotificationSlip)', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.5', 'failcrit', '[Discovery, faction(acting).standing.remove(1 + n_boost)]', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.5', 'portrait', '{Directorate: PortraitEntry(submitter=+1)}', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.5', 'narrative', '\"The Directorate does not ask permission. It records the action and moves on.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.5', 'perspectives', '{Directorate: \"The intelligence warranted the action. The action was authorised. There is nothing further to say.\"}', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.5', 'design_note', '\"Boost model: base cost (faction×1 + native×1 + IntelToken) covers removal of 1 token (threshold 65). Each boost unit = 1 BM-xx = 1 additional token removed, threshold −10. PS scales symmetrically with (1+n): success = −(1+n), successcrit = +(1+n), failcrit = Discovery + −(1+n). Modifier clear = target faction\'s cards only. A Network modifier card auto-triggers off this sweep.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.5', 'arbiter_note', '\"Beat 0: (1) validate base cost paid; (2) n_boost = excess payment ÷ (faction×1+native×1); (3) place n_boost BM-xx on grid slot; (4) lock threshold = 65−10×n_boost; (5) confirm faction(target) has ≥ (1+n_boost) presence tokens at district — reject if not. Beat 3 success: remove target faction\'s modifier cards from district; remove (1+n_boost) presence tokens from faction(target); Directorate PS −(1+n_boost); remove BM-xx to supply. Crit success: PS +(1+n_boost) instead of −(1+n_boost). Fail: dispatch NotificationSlip to target. Crit fail: Discovery (Art 03 §9.4 Step 7b.i — mechanic not yet formally defined); Directorate PS −(1+n_boost).\"', '04___Card_System___Part4c_Directorate.md');
