INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.6', 'narrative', '\"The Directorate does not improvise. The allocation exists because the framework exists. The framework is intact. The allocation is approved.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.6', 'perspectives', '{Directorate: \"The standing record in this ring is clean. What was ordered is being carried out. Resources are allocated accordingly.\"}', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.6', 'design_note', '\"No floor — 0 active Permanents in target ring yields 0 Mandate on success. Count: face-up Directorate Permanent cards in Directorate play area where card.target_district.ring == district(target).ring. Pairs with DIR.CA.7 (same mechanism, PS yield).\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.6', 'arbiter_note', '\"Beat 3: count face-up Directorate Permanent cards in Directorate play area whose target district is in the same ring as district(target). Add that count in Mandate to Directorate supply. Successcrit: +1 Mandate additional. Failcrit: remove 1 Mandate from Directorate supply.\"', '04___Card_System___Part4c_Directorate.md');
