INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.7', 'tagline', '\"Circulate the standing record through closed channels. Demonstrated authority in this ring builds public confidence.\"', '04___Card_System___Part4c_Directorate.md');
