INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.7', 'success', 'faction(acting).standing.add(\n                count(game.active_permanents(faction=acting,\n                      ring=district(target).ring)))', '04___Card_System___Part4c_Directorate.md');
