INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.7', 'portrait', '{Directorate: PortraitEntry(submitter=+1)}', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.7', 'narrative', '\"The Directorate does not announce competence. It demonstrates it — quietly, through the record, through the channels that matter. The public receives the signal without knowing its source.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.7', 'perspectives', '{Directorate: \"The active directives in this ring speak for themselves. We are not making a claim. We are presenting a record.\"}', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.7', 'design_note', '\"PS yield = count of active Directorate Permanents in same ring as target district. 0 Permanents → +0 PS on success. Same counting mechanism as DIR.CA.6 (Mandate yield). Failcrit PS−1: brief traced to Directorate — institutional embarrassment.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.7', 'arbiter_note', '\"Beat 3: count face-up Directorate Permanent cards in Directorate play area whose target district is in the same ring as district(target). Move Directorate PS marker up by that count. Successcrit: +1 PS additional. Failcrit: move PS marker down 1.\"', '04___Card_System___Part4c_Directorate.md');
