INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.8', 'narrative', '\"Enhanced scrutiny has been authorised for this district. All activity here is subject to review. All activity. Including ours.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.8', 'perspectives', '{Directorate: \"The district is under review. Scrutiny means something only when it applies uniformly.\"}', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.8', 'design_note', '\"Applies to all factions including Directorate. Beat 2 ops in district (DIR.CA.1/CA.3/CA.4) unaffected — only Beat 3 rows. Uses existing Modifier tokens (−15) placed by ARBITER per row, not a district-column flag.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.CA.8', 'arbiter_note', '\"Beat 2 Automatic resolution: identify all rows in the resolution grid targeting district(target) at Beat 3. Place a standard Modifier token (−15 threshold) on each row. All factions, no exceptions. Tokens are in place when Beat 3 opens — apply −15 to each op\'s threshold before rolling.\"', '04___Card_System___Part4c_Directorate.md');
