INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.1', 'cost', 'Mandate * 2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.1', 'boost', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.1', 'success', '(\n        arbiter.place(RegulatoryOverrideMarker, district(target)),\n        game.world_condition(\n            scope    = district(target),\n            effect   = presence_placement_action(faction=faction.all_except(Directorate)).cost.add(1),\n            duration = Seasonal,\n            clear_on = (\n                faction(Directorate).influence_tier(target_district) == Absent\n                or game.phase == EndOfQuarter\n            ),\n        ),\n        faction(Directorate).standing.add(1),\n    )', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.1', 'successcrit', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.1', 'fail', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.1', 'failcrit', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.1', 'portrait', '{Directorate: PortraitEntry(submitter=+1)}', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.1', 'ps_framing', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.1', 'narrative', '\"The Directorate does not need to block what it can simply make more expensive.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.1', 'perspectives', '{\n        Directorate: \"Regulatory oversight is the institutional mechanism for managed stability. The cost increase is the signal, not the sanction.\",\n        Ghost:       \"The Directorate taxes the district. We do not need to control the threshold. We only need to observe who stops trying to cross it.\",  \n        Network:     \"One Mandate and the Directorate makes every other faction pay to exist in the district. They call it regulation. We call it a toll.\",  \n    }', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.1', 'design_note', '\"District-level regulatory PA. +1 native cost on all non-Directorate PresenceToken.Add actions in district for remainder of Quarter (Seasonal). Physical marker on district; card stays on table as marker. Counter to Guild STD.PA.3/GUI.PA.1 build chain — raises cost of presence prerequisite. Restriction: Directorate Established+ in district. Multiple P11s may target different districts. Balance review pending playtesting.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.1', 'arbiter_note', '\"Beat 4: place RegulatoryOverrideMarker on declared district. DIR.PA.1 card stays on table as marker. Apply +1 native cost to all non-Directorate presence-placement actions (STD.CA.3 Campaign, STD.PA.1 Open Operations, STD.CA.8 Buy Influence, GUI.PA.1 Civic Works Mandate) targeting this district for remaining Months of Quarter. Directorate PS +1. Clear: Directorate Absent in district (remove immediately) OR Phase 21 cleanup. Multiple markers on different districts tracked independently.\"', '04___Card_System___Part4c_Directorate.md');
