INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.2', 'success', '(\n        arbiter.provide_intel_tokens(\n            target    = target_faction,\n            count     = arbiter.count_attributed_actions(target_faction, months=2),  \n            recipient = Directorate,\n        ),\n        faction(target).standing.remove(1),\n        faction(Directorate).standing.add(1),\n    )', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.2', 'successcrit', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.2', 'fail', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.2', 'failcrit', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.2', 'portrait', '{Directorate: PortraitEntry(submitter=+1)}', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.2', 'ps_framing', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.2', 'narrative', '\"The Directorate does not gather intelligence in the traditional sense. It commissions review.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.2', 'perspectives', '{\n        Directorate: \"We invoke the institutional mechanism for accountability. Whether it yields anything depends on what the target has done publicly.\",\n        Guild:       \"Directorate uses ARBITER to formalize what was publicly attributed. The investigation costs Mandate but produces something the record can verify. Guild respects the process.\",  \n        Syndicate:   \"Directorate asks ARBITER to count what was already on the record. What was not on the record, ARBITER cannot count. That distinction is our operating margin.\",  \n    }', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.2', 'design_note', '\"Directorate intelligence PA via institutional channel. No restriction — always available. Yield: 1 Intel token per publicly attributed covert action against target faction in last 2 months (from successful STD.PA.4 or STD.PA.5 this Quarter). 0 tokens = 3 Mandate wasted (costly gamble without prior groundwork). Distinct from Ghost STD.CA.5 Gather (covert fieldwork). Creates two-step sequence incentive: STD.PA.4/STD.PA.5 → DIR.PA.2.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.2', 'arbiter_note', '\"Beat 4. Count: how many successful STD.PA.4 or STD.PA.5 resolutions named this target faction this Quarter? Provide Directorate with that many Fresh Intel tokens (max 2). Apply PS: target −1, Directorate +1. If count = 0: no tokens delivered. 3 Mandate spent regardless.\"', '04___Card_System___Part4c_Directorate.md');
