INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.3', 'persistence_effect', 'placement(faction.all_except(Directorate), district=district.named, type=DeploymentMarker).blocked', '04___Card_System___Part4c_Directorate.md');
