INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.3', 'cost', 'Mandate * 2 + Capacity * 1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.3', 'boost', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.3', 'success', '(\n        for_each(\n            deployment_marker(faction=faction.all_except(Directorate), district=district.named),\n            arbiter.instruct(marker.owner, move_to=district.where(faction.has_presence), flip_to=Blocked),\n        ),\n        faction(acting).standing.remove(1),\n    )', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.3', 'successcrit', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.3', 'fail', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.3', 'failcrit', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.3', 'portrait', '{Directorate: PortraitEntry(submitter=+1)}', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.3', 'ps_framing', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.3', 'narrative', '\"Movement within the designated zone is now subject to Directorate authorization. Non-compliant presence has been relocated.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.3', 'perspectives', '{\n        Directorate: \"The district is designated. Who enters does so with our permission — or not at all.\",\n    }', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.3', 'design_note', '\"Persistent PA. Card sits in Directorate\'s active PA area on the Overview (not on district tile). Immediate: non-Directorate deployment markers in named district displaced to any district where owning faction has presence, flipped to Blocked. Persistent: non-Directorate deployment marker placement blocked in named district. persistence_condition auto-discards card if Directorate falls below Established. PS −1 at resolution (public backlash). Counter-card removal TBD.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.3', 'arbiter_note', '\"Name the district. Each non-Directorate deployment marker there: owning faction moves it to any district where they have presence, flip to Blocked.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.3', 'value_rating', '4', '04___Card_System___Part4c_Directorate.md');
