INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.6', 'ps_framing', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.6', 'narrative', '\"The Injunction does not prevent the act. It establishes that the act will carry costs the target has not yet calculated.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.6', 'perspectives', '{\n        Directorate: \"The Injunction does not prevent the act. It relocates its costs.\",\n        Ghost:       \"Directorate pre-empts the declaration rather than reacting to it. We recognize this as the structurally correct approach.\",\n        Network:     \"A pre-emptive block on a public act is the Directorate deciding which information enters the record. We have a word for that.\",\n    }', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.6', 'design_note', '\"Card placed in Directorate play area (public, face-up; target faction and target_freeform declared at Phase B). Card IS the persistent condition. Enforcement per Governing Rule 6.1a: Directorate monitors Phase B — when target submits a PA matching target_freeform, Directorate calls it; ARBITER voids the PA (target −1 PS, Dispatch Token consumed per Governing Rule 7.3, card removed). PA resources not yet committed at Phase B (payment is Beat 4 Step 1) — nothing to refund. PAs declared before Injunction resolved at Beat 4 are unaffected — committed board state per Governing Rule 7.2b. Quarter-end expiry: if untriggered at Phase 21, Directorate removes card and recovers 1 Mandate. target_freeform may not be BilateralAgreement — Accords are bilateral and cannot be unilaterally blocked. Distinct from DIR.PA.1 (cost increase on presence placement) and DIR.CA.1 (single-Beat block in one district).\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.6', 'arbiter_note', '\"Beat 4: place card in Directorate\'s play area, face-up, naming target_faction and target_freeform. Card is the standing condition — no separate marker. From this point, monitor Phase B: if the named faction submits a PA matching target_freeform, Directorate may call it — void the PA (target −1 PS, consume Dispatch Token per GR 7.3), then remove this card. No resources refunded to the target (payment isn\'t committed until Beat 4 Step 1). PAs already declared before this card resolved at Beat 4 stand — do not retroactively block them (GR 7.2b). If untriggered by Phase 21: remove the card, return 1 Mandate to Directorate.\"', '04___Card_System___Part4c_Directorate.md');
