INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.7', 'persistence_effect', 'game.board_condition(\n        scope  = district(target_district),\n        effect = on(deployment_marker.placed(faction=target_faction, district=target_district)):\n                     arbiter.set(trigger.marker, face=Blocked),\n    )', '04___Card_System___Part4c_Directorate.md');
