INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.7', 'ps_framing', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.7', 'narrative', '\"The checkpoint doesn\'t ask for papers. It just doesn\'t open.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.7', 'perspectives', '{\n        Directorate: \"The district is calm because nothing enters it uninvited. That is not oppression. That is order.\",\n        Ghost:       \"Fewer new arrivals means fewer variables. We understand the appeal of a district that stops changing while you\'re not looking at it.\",  \n        Guild:       \"A permit that means nothing at the checkpoint isn\'t governance. It\'s a wall we didn\'t get to help design.\",  \n    }', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.7', 'design_note', '\"A massive territorial denial tool. Blocks physical movement (which is public and enforceable) rather than targeting blind covert space. Directorate\'s own markers are exempt — a curfew is enforced by the authority declaring it, not against it.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.7', 'arbiter_note', '\"Once the next Placement phase begins: any non-Directorate deployment marker placed in target_district is immediately flipped to its Blocked face (Art 03 Upkeep Step 4\'s existing mechanic — returns to hand without converting at next Upkeep). Standing condition clears once that Placement phase resolves, per persistence_clearing_trigger.\"', '04___Card_System___Part4c_Directorate.md');
