INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.8', 'ps_framing', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.8', 'narrative', '\"The subpoena doesn\'t argue. It just offers a choice of how to lose.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.8', 'perspectives', '{\n        Directorate: \"We do not act without evidence. What we found justifies what we are demanding now.\",\n        Ghost:       \"They needed something real before they moved. That is more discipline than most institutional actors manage.\",  \n        Network:     \"The evidence that triggered this was gathered in secret and will never be shown. We are asked to trust a subpoena built on a source no one gets to question.\",  \n    }', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.8', 'design_note', '\"Cost uses a faction-keyed Intel Token: Directorate \'found out something\' that justifies the legal action. Target elects to pay 2 of their own native resource, or decline and lose 2 Public Standing instead — ElectPlayer, matching SYN.PA.1\'s confirmed shape.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.8', 'arbiter_note', 'None', '04___Card_System___Part4c_Directorate.md');
