INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.9', 'narrative', '\"The charter doesn\'t announce a target. It just quietly explains why the whole ring already answers to the same office.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.9', 'perspectives', '{\n        Directorate: \"Authority that only sits in one place is a garrison. We prefer it to be infrastructure.\",\n        Guild:       \"Expansion that doesn\'t overextend its own supply lines — sound structural planning, whoever\'s doing it.\",  \n        Network:     \"Three districts absorbed the same authority in one afternoon, and nobody had to explain why. That\'s the part worth reporting.\",  \n    }', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.9', 'design_note', '\"First DIR Territory|Add|PresenceToken card — closes a headline win-path gap. Places 1 token in target district + 1 token in each same-ring-adjacent district, up to N = min(2, active Directorate Permanents in that ring) — same counting mechanism as CA.6 Institutional Audit / CA.7 Institutional Brief, reinforcing Directorate\'s compounding-authority engine. Ring-spread (not single-district stack) is deliberate: Directorate\'s win path is Established (2+, second place) in more districts than any other faction, not Dominant — breadth beats depth. N naturally caps at 2 (max same-ring neighbors per district, confirmed against board geometry), so ceiling is modest: at most 3 districts touched, 1 token each. Each placement independently respects the 6-chip-per-district cap (GR 8.1) — a capped destination is skipped, not a card-voiding failure. Early game (0 Permanents) = ordinary single-district placement, same as Standard; late game = Directorate\'s strongest expansion tool, consistent with the audit\'s \'compounds over 2-3 Quarters\' finding.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.9', 'arbiter_note', 'None', '04___Card_System___Part4c_Directorate.md');
