INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.10', 'narrative', '\"The number is accurate. Whether the city reads it as reassurance or as a warning is not something Directorate gets to decide.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.10', 'perspectives', '{\n        Directorate: \"We publish the count because the count is real. What the public does with it afterward is the public\'s business.\",\n        Guild:       \"A demonstrated number is worth more than an asserted one. We\'d stake our own reputation on the same math.\",  \n        Network:     \"A number Directorate counted, about Directorate\'s own reach, printed by Directorate. We\'ll run our own tally before we repeat theirs.\",  \n    }', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.10', 'design_note', '\"Public counterpart to DIR.CA.7 Institutional Brief (covert, Permanent-count-scaled, ring-scoped). Distinct scaling basis to avoid duplication: N = count of districts city-wide where Directorate holds Established+ tier — a simple tally of physical Established markers already on the board (same counting mechanism CA.6/CA.7 use for Permanents; no ARBITER judgment call, GR 6.1/4.7b-safe). Flat threshold=50 (matches CA.2/CA.6/CA.7 precedent) — the gamble is in the outcome, not compounded difficulty. Success and fail both scale with N (not the usual \'fail = no effect\') — a bigger public show of institutional reach is a bigger bet in both directions: it can read as reassuring stability or as authoritarian overreach. Failcrit\'s N+1 penalty represents the claim spectacularly backfiring. Cost kept cheap and mono (Mandate x2) — the filing itself is trivial; the risk lives entirely in the public\'s reaction, not the resource spend.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.10', 'arbiter_note', '\"Beat 4: count districts where Directorate currently holds Established+ tier (visible via Established/Dominant markers already on board) = N. Roll d100 vs threshold 50. Success: Directorate PS += N. Successcrit: PS += N+1. Fail: Directorate PS -= N. Failcrit: PS -= N+1.\"', '04___Card_System___Part4c_Directorate.md');
