INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.11', 'ps_framing', 'None', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.11', 'narrative', '\"The hearing doesn\'t undo the regulation. It just proves the regulation had to survive being asked.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.11', 'perspectives', '{\n        Directorate: \"Every regulation we write can be challenged. Every challenge that fails still pays us for the trouble of hearing it.\",\n        Ghost:       \"We supply the token that makes the process cost something. A due process nobody has to pay for isn\'t due process — it\'s theater.\",  \n        Syndicate:   \"Petition, pay, and if you win, Directorate still keeps the fee. That\'s not a hearing. That\'s a toll booth with a hearing room attached.\",  \n    }', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.11', 'design_note', '\"Resolves the long-standing open counter-card design gap for Permanent PAs, originally named specifically for Entry/Exit Controls but generalized here to all Directorate standing PAs. Doctrinal extension of CA.8 Enhanced Scrutiny\'s self-inclusive principle (\'scrutiny means something only when it applies uniformly\') from \'Directorate submits to its own suppression\' to \'Directorate\'s regulations answer to due process.\' Atomic resolution (pay + prove, immediate removal) — nothing is tracked or remembered across time, avoiding the untracked per-faction exemption-state problem an earlier draft of this card (a Guild-specific construction-permit concept) ran into. Cost-match is a simple physical lookup (read the target PA\'s own printed cost directly off that card), not an ARBITER calculation — GR 6.1 / Design Pillar 4.7b-safe. Directorate profits from every invocation (full cost refund + an Intel token) regardless of which PA is targeted or by whom — a genuine income mechanism, not a giveaway; nothing prevents Directorate from re-declaring the same regulation later at its own cost. Scoped to Directorate\'s own standing PAs only, not any faction\'s — matches the original named case and avoids becoming an unscoped general-purpose Permanent-PA-removal tool that would need its own balance pass.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.PA.11', 'arbiter_note', '\"Beat 4: Directorate plays this card once — establishes the standing due-process institution (no target district; applies game-wide, for the rest of the session). From this point forward: any faction may, at any time, name one currently active Directorate-owned standing Public Act and pay Directorate an amount matching that PA\'s own printed cost, plus 1 Intel Token (Fresh or Stale), to have it immediately removed. Verify the payment matches the target PA\'s printed cost and that the Intel Token is not Expired, then remove the targeted PA and announce.\"', '04___Card_System___Part4c_Directorate.md');
