INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.MOD.2', 'design_note', '\"Syndicate-targeted variant of DIR.MOD.1. Directorate\'s doctrine makes no distinction between rogue capital and rogue information — Syndicate\'s gray-market acquisitions are the same institutional threat as Network\'s broadcasts. Syndicate portrait flat=-1 on fire: the Syndicate\'s response to having presence removed is public and traceable. Narrower trigger window than generic; reliable in SYN-heavy games.\"', '04___Card_System___Part4c_Directorate.md');
