INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.MOD.3', 'design_note', '\"Ring 1–constrained variant of DIR.MOD.1. Core ring is institutional home territory — Directorate removes presence without needing Established status. Reflects doctrine: Directorate\'s authority in the Core is structural, not earned faction by faction. Strongest DIR enforcement React — no restriction to work around.\"', '04___Card_System___Part4c_Directorate.md');
