INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.MOD.6', 'design_note', '\"Environmental shaping. Triggers when ARBITER reveals a World Event. The card is placed face-up on the Directorate\'s Faction Resolution Grid as a standing condition for the rest of the Quarter, imposing a -10 difficulty penalty on any opponent PA targeting a district where Directorate holds Established influence or higher. Solves the \'world event extension\' gap by letting Directorate piggyback on the World Event phase to declare their own global environmental constraint. Legally escapes Art 00a §9.1 because it modifies action difficulty (9.1a), not resource income. Cost reasoning: Exposure represents the widespread public broadcast necessary to enforce an emergency lockdown. ⚠ XA-54: \'world_event.played\' assumes \'World Event\' is either a defined Broadcast Card subtype or a synonym for all Broadcast Cards — Broadcast Card design is open; trigger frequency depends entirely on how many World Events exist in the Broadcast Deck.\"', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('DIR.MOD.6', 'arbiter_note', 'None', '04___Card_System___Part4c_Directorate.md');
