INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.1', 'tagline', '\"Expose and cancel a rival\'s most costly unresolved operation before it fires.\"', '04___Card_System___Part4d_Network.md');
