INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.1', 'cost', 'Exposure * 1 + Findings * 1', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.1', 'success', '[\n        game.announce(faction(target).op(beat=3, unresolved=True, selection=highest_cost), discovery=True, public=True),\n        game.cancel(faction(target).op(beat=3, unresolved=True, selection=highest_cost)),\n    ]', '04___Card_System___Part4d_Network.md');
