INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.1', 'narrative', '\"The Network does not need to know everything — only enough to make the right question public.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.1', 'perspectives', '{Network: \"We do not reveal everything. We reveal the piece that makes everything else visible.\"}', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.1', 'design_note', '\"Pre-execution discovery + cancellation model: target op cancelled, resources lost, PS reduction applies. Cross-resource cost 1 Exposure + 1 Findings by design to force trade dependency. Beat 3 initiative incentive: Network benefits from going first; fizzle risk if target ops resolve before Leak fires. ps_framing for target PS reduction pending finalization. Subject is CovertOperation, not District: DistrictTile has no Reveal in comp_verb_phase — the card reveals and cancels the operation, not the district itself.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.1', 'arbiter_note', '\"Among target faction\'s unresolved covert operations in the Beat 3 grid, identify the operation with the highest total resource cost submitted. Publicly announce: operation name, acting faction, target district. Cancel the operation — it does not resolve; resources submitted are lost. Target faction PS reduction applies (discovery consequence — ps_framing pending finalization). If no unresolved operations remain for target faction at time of Leak\'s resolution, operation has no effect — Network\'s resources spent. Network\'s acting faction identity is not announced at resolution.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.1', 'value_rating', '4', '04___Card_System___Part4d_Network.md');
