INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.2', 'narrative', '\"The act of disclosure is not only a tactic. It is a resource. The Network learned this before anyone else at this table.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.2', 'perspectives', '{Network: \"We revealed something. Now we can reveal something more. The loop is already running.\"}', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.2', 'design_note', '\"Replaces NET.CA.2 Source Protection (retired S51). Source Protection was doctrinally misaligned — protecting attribution is Ghost\'s register, not Network\'s. Pairs with NET.CA.1 Leak and NET.CA.3 Breaking News.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.2', 'arbiter_note', '\"At Beat 3 cleanup, check whether any Network Reveal card resolved successfully this round. If yes, deliver 1 Exposure to Network\'s resource pool. If no Reveal resolved, card takes effect but produces nothing — the slot cost was the investment.\"', '04___Card_System___Part4d_Network.md');
