INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.3', 'failcrit', 'game.dispatch(NotificationSlip(recipient=faction(target)))', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.3', 'portrait', '{Network: PortraitEntry(submitter=+1)}', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.3', 'narrative', '\"The story was going to come out. We simply chose the timing.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.3', 'perspectives', '{\n        Network: \"We don\'t ask permission to broadcast. We decide when.\",\n    }', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.3', 'design_note', '\"Point-in-time forced reveal, avoiding the cross-beat state tracking a notification-redirect model would require (Governing Rule 6.1). Fills Network\'s forced-transparency FactionSpecific slot at L1. Beat 2: ARBITER announces target\'s first Beat 3 queue entry to all players; VM-xx placed to flag public Beat 3 resolution. Distinct from NET.CA.1 Leak (Beat 3 cancel + reveal) and GHO.CA.2 Intercept (private IS-xx to Ghost). Fizzle: if target has no committed Beat 3 ops at Beat 2, announce fizzle; cost spent. Second Beat 2 d100 card alongside GHO.CA.2 — procedure gap in Art 03, not yet formalized.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.3', 'arbiter_note', '\"Network has played Breaking News targeting faction X. Roll d100 (threshold 50 + PS modifier). Success: check faction X\'s Beat 3 queue. If empty: announce \'No operations queued for faction X — Breaking News fizzles\'; cost spent, no further effect. Otherwise: identify faction X\'s first entry in Beat 3 resolution order; announce to all players: card name, type, declared targets; place VM-xx on that card in the grid. VM-xx procedure at Beat 3: when this card is reached, announce it publicly, roll d100 visibly, announce outcome to table, then remove VM-xx. Do not announce Network as acting faction. Crit success: reveal and place VM-xx on ALL of faction X\'s Beat 3 queue entries. Fail: cost spent, no announcement. Crit fail: dispatch NotificationSlip to faction X only. Do not announce Network.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.3', 'value_rating', '4', '04___Card_System___Part4d_Network.md');
