INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.6', 'narrative', '\"The Network knows: sometimes you spend credibility like currency. This is one of those times.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.6', 'perspectives', '{Network: \"What we have built is not a goal. It is a tool. And sometimes a tool must be spent.\"}', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.6', 'design_note', '\"PS −2 is a success effect, not a cost — PS is non-fungible and cannot appear in the cost field (Art 04 §6.2). target_faction required: tokens must be keyed at Dispatch. Single use per play; 2:1 ratio prevents cheap IntelToken arbitrage.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.6', 'arbiter_note', 'None', '04___Card_System___Part4d_Network.md');
