INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.7', 'narrative', '\"No one announces this. The message moves because the people carrying it are already there, already part of the district\'s daily traffic. The signal is readable only to those who know how to read it.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.7', 'perspectives', '{Network: \"We\'re not running outreach. We\'re making our existing presence legible to people who\'ve been ignoring it.\"}', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.7', 'design_note', '\"Restriction: Network IL in target district ≤ Established (Dominant excluded — at Dominant, the street already knows). Successcrit delta: +1 chip in target district + +1 PS additional on top of success\'s +1 PS (total on successcrit: +2 PS, +1 chip placed).\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.7', 'arbiter_note', '\"Beat 3: Network IL in target district must be ≤ Established (Dominant: card invalid, do not resolve). On success: +1 PS to Network. On successcrit: additionally place 1 Network chip in target district AND +1 PS (total: +2 PS, +1 chip placed). Failcrit: −1 PS.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.CA.8', 'id', '\"NET.CA.8\"', '04___Card_System___Part4d_Network.md');
