INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.PA.1', 'fail', '(\n        faction(target).standing.remove(1 * count(intel_token(target=faction(target)).spent)),  \n        faction(Network).standing.remove(1),\n    )', '04___Card_System___Part4d_Network.md');
