INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.PA.2', 'narrative', '\"Network presence does not require a march. It requires a broadcast and the communities that were already listening.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.PA.2', 'perspectives', '{\n        Network:     \"We are already there. This makes it visible.\",\n        Syndicate:   \"Network deepens without purchasing. No Accord, no offer fee, no formal mechanism. The community already listening becomes the position. Efficient.\",  \n        Directorate: \"Network consolidates three Established positions simultaneously without a single permit or notification. The Directorate marks this as unregulated expansion and files accordingly.\",  \n    }', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.PA.2', 'design_note', '\"Broadcast-derived presence PA. Deepens existing foothold (Established+) rather than expanding into new territory. Scaling cost: 2 Exposure (1 district), 3 (2 districts), 4 (3 districts). Partial resolution: if a named district fails Established+ restriction at Beat 0, that district is dropped from resolution; remaining valid districts proceed; cost already committed. Replaces Open Record Request (unworkable) Cost reasoning: District native resources represent the local on-the-ground support required to organize a massive rally.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.PA.2', 'arbiter_note', '\"Phase B: Network names 1–3 districts. Cost calculated (2 + extras) and committed. Beat 0: check each named district for Established+ restriction. Drop invalid districts from resolution. Beat 4: place 1 presence token in each valid district. Network +1 PS.\"', '04___Card_System___Part4d_Network.md');
