INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.PA.3', 'persistence_clearing_trigger', '\"target_faction complied (open hand) for one full Covert Dispatch this Quarter → card clears at end of that Covert Dispatch; or Quarter end\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.PA.3', 'persistence_effect', '\"Each Covert Dispatch of remaining Months: target faction elects comply (lay all held cards face-up on table; covert ops proceed normally this Covert Dispatch) or resist (dispatch case disabled this Month — no covert submissions). Comply once → card clears.\"', '04___Card_System___Part4d_Network.md');
