INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.PA.3', 'ps_framing', 'None', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.PA.3', 'narrative', '\"The story is already written. The only question is whether the subject chooses the cameras or the consequences.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.PA.3', 'perspectives', '{\n        Network:     \"We are not exposing secrets. We are establishing accountability. The distinction matters to us.\",\n        Directorate: \"Network has appointed itself an oversight authority. The Directorate notes this. It will not be forgotten.\",\n    }', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.PA.3', 'design_note', '\"Hand-visibility model replaces a dispatch-case forced-reveal mechanism — simpler L1 execution, genuine comply/resist decision friction. Comply once → card clears (the faction gave the interview; Network moves on). Resist → covert submissions disabled that Month; card persists. Natural expiry: Quarter end. SuccessCrit: obligation activates + target −1 PS (story breaks big). FailCrit: Network −1 PS (reckless broadcast, story didn\'t land). Art 03 Covert Dispatch procedure required. Subject = FactionHand — 04b validation needed.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.PA.3', 'arbiter_note', '\"Network has declared Live Coverage against faction X. Place card in Network\'s active PA area, face-up; faction X announced. Effect begins next Covert Dispatch. Each Covert Dispatch while Live Coverage is active: at start of Covert Dispatch announce — \'Live Coverage is active against [Faction X]. Faction X: comply (lay all held cards face-up on your table area for Covert Dispatch — cards remain in hand; covert ops proceed) or resist (forfeit covert submissions this Month).\' If faction X complies: covert submissions proceed normally; at end of Covert Dispatch, remove Live Coverage from Network\'s active PA area. If faction X resists: faction X does not open their dispatch case this Covert Dispatch; Live Coverage remains in play. Cards laid face-up during compliance are still counted as in hand. Network identity as declaring faction is already public (Phase B declaration).\"', '04___Card_System___Part4d_Network.md');
