INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.MOD.1', 'narrative', '\"The district was already moving. Network didn\'t start the change — it arrived at the same time the change did. Two signals crossing in the open.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.MOD.1', 'perspectives', '{Network: \"We don\'t need to create the disruption. We need to be in position when it happens.\"}', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.MOD.1', 'design_note', '\"Trigger: any PA success that causes a board state change (influence chip or structure block placed or removed in district). Target district fixed by trigger — not a free choice. No restriction on Network existing presence. Modifier card schema fields are CA-convention placeholders pending reconciliation.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.MOD.1', 'arbiter_note', '\"Beat 4: when a PA success produces a board state change in district X (influence chip count changes, or structure block placed/removed), Network may announce Pirate Transmitter. Confirm trigger validity. Network spends 1 Exposure and rolls d100 (threshold 50, usual modifiers). Success: place 1 Network chip in district X. Successcrit: +1 PS additional. Fail: no effect. Failcrit: −1 PS.\"', '04___Card_System___Part4d_Network.md');
