INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.MOD.6', 'design_note', '\"Opportunistic Baryo expansion React. When any faction places presence in Ring 3 (Baryo), Network may place 1 chip in any Ring 3 district where it has presence (or adjacent — TBD at design pass). Network\'s community-relationship model means others\' activity in Baryo draws Network in. Delivers §5a \'wide Presence coverage, Baryo outward\' at the modifier deck level.\"', '04___Card_System___Part4d_Network.md');
