INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.MOD.11', 'design_note', '\"Network doesn\'t block the legal act (Directorate\'s job). Instead, Network weaponizes the public\'s reaction to the act, ensuring the target pays a heavy PR price for whatever they just did. Target\'s PA resolves normally — this is pure PS backlash, not interference with the PA\'s mechanical outcome.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.MOD.11', 'arbiter_note', '\"On trigger (any faction submits a PA): confirm Network pays Exposure(1). Target PA resolves normally in full. Additionally: target faction\'s PS −2 (extreme public backlash), Network\'s Exposure +1.\"', '04___Card_System___Part4d_Network.md');
