INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.MOD.12', 'design_note', '\"A direct counter to hidden targets. By spending 1 Exposure, Network strips the opponent\'s tactical ambiguity for the entire round, letting other factions prepare defenses or negotiate before Beat 4. The PA is locked in and resolves normally at Beat 4 — Network doesn\'t stop it, just exposes it.\"', '04___Card_System___Part4d_Network.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('NET.MOD.12', 'arbiter_note', '\"Reacts at Art 03 §9.2.0 when an opponent places a PA with a face-down Target Profile. Network announces the React and pays Exposure(1). ARBITER flips the Target Profile face-up immediately. The PA is locked in and resolves normally at Beat 4; the target is public knowledge for the rest of the round.\"', '04___Card_System___Part4d_Network.md');
