INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.1', 'narrative', '\"The Syndicate does not need to be somewhere to profit from it. Ownership and presence are different things.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.1', 'perspectives', '{Syndicate: \"We own the revenue stream. Whether we are physically present is irrelevant.\"}', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.1', 'design_note', '\"Immediate delivery at Beat 3 resolution. Core cost = action slot; 2:1 Capital:native is the unit rate. Boost: player submits multiples of 2 Capital; each unit yields 1 additional native. No declaration required.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.1', 'arbiter_note', '\"Beat 0: if extra Capital submitted beyond 2, calculate n = (total − 2) / 2; must be whole number or reject. Beat 3: grant Syndicate (1 + n) units of target district\'s native resource.\"', '04___Card_System___Part4e_Syndicate.md');
