INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.3', 'cost', 'Capital * 3 + Findings * 1 + Exposure * 1', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.3', 'success', '(\n        game.transfer(district(target).faction(target).structure(1), faction(acting)),\n        game.dispatch(faction(target), faction(target).native * 1),\n    )', '04___Card_System___Part4e_Syndicate.md');
