INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.3', 'narrative', '\"Everything in New Meridian has a price. The Syndicate is the only faction honest about this.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.3', 'perspectives', '{Syndicate: \"We made a fair offer. The market determined the value. We accepted the market\'s judgment.\"}', '04___Card_System___Part4e_Syndicate.md');
