INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.4', 'narrative', '\"The Syndicate does not wait to find out. They price the outcome in advance.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.4', 'perspectives', '{Syndicate: \"We did not lose those resources. We placed them where the problem would be. There is a difference.\"}', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.4', 'design_note', '\"Capital declared at Dispatch on target profile. Beat 0: retained (not drained). Beat 2: distributed across target_faction Beat 3 ops targeting Syndicate, first-to-last, until exhausted. Beat 3: full coverage = void + Capital to submitter case; partial = −50 marker + Capital to submitter case. No ops from target_faction = windfall to return case. Wager structure: Syndicate bets positionally — wrong bet wastes Capital, correct bet nullifies threat.\"', '04___Card_System___Part4e_Syndicate.md');
