INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.8', 'narrative', '\"The deed was filed before the foundation was poured. That is how the Syndicate prefers it.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.8', 'perspectives', '{Syndicate: \"We don\'t need to be there. We just need to be on the paperwork.\"}', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.8', 'design_note', '\"Delivers Grant Deed (GD-01) component (ARBITER tableau → Syndicate case → hand at Debrief). Grant Deed is a tripwire Issued ModReactCard (acquisition=Issued) held in faction hand; fires when any faction places a structure block in the named district. Fire effect: +1 Presence Token + 1 Structure Block for deed holder in named district. GR 8.2 governs structure placement (blocked if holder already has structure there; Presence Token still placed). No board marker from this card. Automatic resolution — no crit or fail. Multiple deeds on same district permitted; cost-governed.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.8', 'arbiter_note', '\"Take 1 blank Grant Deed (GD-01) from ARBITER tableau. Write target district name and Syndicate as holder. Place in submitting faction\'s Dispatch Case. Grant Deed moves to hand at Debrief.\"', '04___Card_System___Part4e_Syndicate.md');
