INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.9', 'portrait', '{Syndicate: PortraitEntry(submitter=+1)}', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.9', 'narrative', '\"The Syndicate does not displace people. It acquires their positions. There is a difference, legally speaking.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.9', 'perspectives', '{Syndicate: \"We purchased the relationship. The people can stay. Their affiliation is now ours.\"}', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.9', 'design_note', '\"Distinct from SYN.CA.3 Hostile Acquisition (StructureBlock). Replaces ALL target presence in district with Syndicate presence at same count (same control tier — neutral effect on tier, swing in ownership). Requires Ghost-sourced faction-keyed Intel token. Intel token creates structural link between Ghost and Syndicate — neither faction announces it publicly.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.9', 'arbiter_note', '\"At resolution: count target\'s presence tokens in district. Remove all of them. Place equal count of Syndicate presence tokens in same district. Net tier unchanged; ownership transferred. Deliver NotificationSlip to target on crit fail. Crit success: +1 Capital to Syndicate.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.10', 'card_id', '\"SYN.CA.10\"', '04___Card_System___Part4e_Syndicate.md');
