INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.10', 'target_freeform', '(\n        incoming_party = faction(any),\n        \n        \n        \n    )', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.10', 'affinity', 'None', '04___Card_System___Part4e_Syndicate.md');
