INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.10', 'success', 'target_object.alter(\n        type     = NamedParty,\n        outgoing = target_faction,\n        incoming = target_freeform.incoming_party,\n    )', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.10', 'successcrit', 'faction(target_freeform.incoming_party).player.elect(\n        target_object.alter(type=Terms, clause=any_numeric, new_value=player_chosen_int),\n    )', '04___Card_System___Part4e_Syndicate.md');
