INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.10', 'portrait', '{Syndicate: PortraitEntry(submitter=+1)}', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.10', 'narrative', '\"The form in the Accord Placement Area is updated. The parties to the original agreement learn about it at the same time as everyone else.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.10', 'perspectives', '{\n        Syndicate:   \"The agreement was always an asset. We\'ve restructured who holds it.\",\n        Ghost:       \"The Accord changed hands without a handshake. The power to do that is worth understanding.\",\n        Network:     \"A binding agreement — restructured by someone who wasn\'t party to it, without notice. This is what unaccountable capital does.\",\n        Directorate: \"A covert restructuring of a binding agreement. The incoming party is now bound. Noted.\",\n        Guild:       \"Agreements don\'t restructure themselves. Someone just demonstrated they can override the process.\",\n    }', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.10', 'design_note', '\"Completes the Accord manipulation suite with SYN.CA.11 Redline: CA.10 controls who is bound; CA.11 controls what the terms say. Economy|Corrupt|AccordCard — party names on the Accord form are written records; replacement is a Corrupt operation. ARBITER makes the physical alteration at Beat 3 per Art 06 §9.10 and announces publicly (the change is public; the acting faction remains covert). No consent required from either party (Art 06 §9.10, L205). Outgoing_party may be Syndicate (self-exit, forcing obligations onto incoming party). Incoming_party may be Syndicate (self-insertion to acquire another faction\'s Accord position). Restriction: incoming_party not already a named party on the same Accord. Crit success: incoming party — the involuntarily inserted faction — elects one numeric term change at the table; gives them a single renegotiation concession. Supersedes SECONDARY OBLIGATIONS gap concept.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.10', 'arbiter_note', '\"Covert Dispatch: acting faction writes on TP declared-parameters line: incoming party. Beat 0: verify restriction — outgoing party is named on target Accord; incoming party is not. Beat 3: roll d100. On success (≤50): locate Accord form in Accord Placement Area; strike outgoing party name; write incoming party name; announce to table: \'[Outgoing] replaced by [Incoming] on [Accord]. All terms now bind [Incoming].\' On crit success (01–05): apply named party change as above; then address incoming party player: \'You may alter one numeric term in this Accord — name the clause and state the new value.\' Apply declared change per Art 06 §9.10 Alter/Terms. On fail: no effect; cost spent. On failcrit (96–00): no Accord change; announce acting faction publicly; apply Syndicate −2 PS.\"', '04___Card_System___Part4e_Syndicate.md');
