INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.6', 'narrative', '\"The Syndicate does not steal from the river. They build a weir.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.6', 'perspectives', '{Syndicate: \"We invested in the district\'s infrastructure. Why shouldn\'t we see what moves through it?\"}', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.6', 'design_note', '\"Positional wager — resolved fully at Beat 2. ARBITER checks Beat 3 dispatch queue for any card targeting district(target). If found: Intel token keyed to the submitting faction of the first card in resolution order delivered to Syndicate\'s case. If no Beat 3 card targets the district: cost spent, no effect. Covert — other factions cannot observe.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.6', 'arbiter_note', '\"At Beat 2 resolution: check Beat 3 dispatch queue for any card targeting district(target). If found: deliver IntelToken keyed to that card\'s submitting faction (first in resolution order) to Syndicate\'s case; portrait fires. If none found: cost spent, no effect, portrait does not fire. Covert — do not announce.\"', '04___Card_System___Part4e_Syndicate.md');
