INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.7', 'narrative', '\"The information was gathered properly. What is done with it is simply business.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.7', 'perspectives', '{Syndicate: \"We don\'t call it blackmail. We call it an incentive structure with consequences attached.\"}', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.7', 'design_note', '\"Covert submission; private notification at Beat 3 (ARBITER whispers to target — not public). Target elects comply or resist. Comply: pay resources (amount TBD). Resist: presence tier −1 at target district + PS −1. Syndicate PS −1 always. Covert ElectPlayer procedure required in Art 03 before Issues Resolved.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.7', 'arbiter_note', '\"Beat 3: whisper privately to target faction — inform them of blackmail attempt. Target elects comply or resist (not announced publicly). On comply: transfer [X native TBD] from target to Syndicate. On resist: reduce target\'s presence tier at named district by 1; reduce target PS by 1. Regardless of outcome: reduce Syndicate PS by 1.\"', '04___Card_System___Part4e_Syndicate.md');
