INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.11', 'narrative', '\"The document in the placement area is a public record. It has always been a public record. The number in the third clause has always been that number. If it seems different from what you remember — you\'re probably misremembering.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.11', 'perspectives', '{\n        Syndicate:   \"Leverage doesn\'t expire. It just changes shape.\",\n        Ghost:       \"We noticed the discrepancy. We are still determining whether it was us, them, or the original terms.\",\n        Network:     \"Someone revised the Accord. No one is claiming it. That\'s the story.\",\n        Directorate: \"The written record is the law. We will find out who changed this.\",\n        Guild:       \"We build to the spec we signed. If the spec changed, we need to know now.\",\n    }', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.11', 'design_note', '\"Syndicate\'s only Information-layer covert op. Effect is public (form changes) but actor is covert — unique table dynamic. Valid clause targets: fill-in values that are numeric or ordinal (resource quantity, influence tier, Quarter number). Prohibited: clause rows with only named entries (district name, PA type) — not numeric alterations. declared_clause and declared_value sourced from Target Profile declared-parameters line.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.11', 'arbiter_note', '\"Acting faction declares at Covert Dispatch: (a) target Accord by named parties, (b) clause row to alter, (c) replacement value — all written on Target Profile declared-parameters line. On success at Beat 3: locate declared Accord form in Accord Placement Area; apply Alter/Terms per Art 06 §9.10 — write new value; acting faction identity not disclosed. If declared Accord has been removed before Beat 3 resolution, treat as fail. Alteration resolves in submission order; subsequent Beat 3 ops see altered terms.\"', '04___Card_System___Part4e_Syndicate.md');
