INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.12', 'design_note', '\"Covert form acquisition — distinct from STD.CA.9 which routes through public Accord channels. Syndicate obtains a blank form privately; fills it in and deploys at Debrief on their own terms, without signaling intent beforehand. Cross-resource cost: Capital×1 (Syndicate native — the commercial motivation) + Mandate×1 (institutional access required to obtain the form — Directorate\'s procedural domain). Pairs with SYN.MOD.11 Signature on File: Boilerplate provides the form; Signature on File forces acceptance. Closes a parasitic-posture gap — Syndicate now has Accord-formation capability.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.CA.12', 'arbiter_note', '\"On success: retrieve one blank Accord form from supply and place it in Syndicate\'s dispatch case. Syndicate may fill it in and table it at Debrief (Art 06 §9). Covert — do not announce delivery.\"', '04___Card_System___Part4e_Syndicate.md');
