INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.1', 'cost', 'Capital * 1', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.1', 'boost', 'None', '04___Card_System___Part4e_Syndicate.md');
