INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.1', 'on_accept', '(\n        arbiter.remove(presence_chip, district=target_district, faction=target, count=n),\n        arbiter.place(presence_chip, district=target_district, faction=Syndicate, count=n),\n        faction(target).resource(capital).add(2 * n),  \n        faction(Syndicate).standing.add(1),\n        faction(target).standing.add(1),\n    )', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.1', 'on_decline', '(\n        faction(Syndicate).standing.add(1),\n        faction(target).standing.remove(1),\n    )', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.1', 'portrait', '{Syndicate: PortraitEntry(submitter=+1)}', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.1', 'ps_framing', 'None', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.1', 'narrative', '\"Syndicate does not take what it can buy. The offer is always made first. What the other faction does with it is their business.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.1', 'perspectives', '{\n        Syndicate: \"This is the formal mechanism. We are not here to take — we are here to acquire. The distinction matters.\",\n        Network:   \"Syndicate makes the offer at The Table where everyone watches. Whatever the target decides, their answer is on the record. That is also useful to us.\",  \n        Guild:     \"Syndicate offers Capital for positions Guild built through construction and sustained through presence. We did not build it to sell. That is not a position the offer changes.\",  \n    }', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.1', 'design_note', '\"Public counterpart to SYN.CA.3 Hostile Acquisition. 1 Capital offer fee non-refundable. Balance payment (2n Capital) conditional on acceptance, paid at Beat 4. Scaling: n=2 (Established min) = 4 Capital; n=6 (Dominant max) = 12 Capital. On accept: both PS +1. On decline: Syndicate +1, target −1. Beat 4 resolution — not Debrief.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.1', 'arbiter_note', '\"Phase B: Syndicate names target faction, district, token count (n). 1 Capital offer fee committed. Beat 0: restriction check (target Established+). Beat 4: target faction publicly accepts or declines. On accept: transfer n presence tokens from target to Syndicate; Syndicate pays 2n Capital to target from supply; both +1 PS. On decline: Syndicate +1 PS, target −1 PS. Offer fee (1 Capital) is not returned in either case.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.2', 'id', '\"SYN.PA.2\"', '04___Card_System___Part4e_Syndicate.md');
