INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.2', 'tagline', '\"Declare a public capital investment in a district — rewarding whoever holds Dominance at next Upkeep.\"', '04___Card_System___Part4e_Syndicate.md');
