INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.2', 'success', '(\n        arbiter.place(DividendMarker(value=2, resource=Capital, district=target_district)),\n        faction(Syndicate).standing.add(1),\n        game.world_condition(\n            scope    = district(target_district),\n            effect   = faction(district(target_district).dominant).resource(Capital).add(2),\n            duration = Seasonal,\n            trigger  = game.phase == Upkeep,\n            clear_on = DividendMarker(district=target_district).claimed == True OR game.phase == EndOfQuarter,\n        ),\n    )', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.2', 'successcrit', 'None', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.2', 'fail', 'None', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.2', 'failcrit', 'None', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.2', 'portrait', '{Syndicate: PortraitEntry(submitter=+1)}', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.2', 'ps_framing', 'None', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.2', 'narrative', '\"Syndicate backs positions, not factions. The investment is in the district. The winner claims it.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.2', 'perspectives', '{\n        Syndicate:   \"We do not choose who collects. We choose where the capital sits. That is sufficient leverage.\",\n        Ghost:       \"Syndicate places the incentive and removes themselves from the contest. The district will spend three months fighting over two Capital. We understand the patience required to let mechanisms run.\",  \n        Directorate: \"Syndicate places two Capital in a district and calls it public investment. The Directorate notes there is no permit, no declared ownership, and no regulatory oversight on what the marker represents.\",  \n    }', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.2', 'design_note', '\"Persistent economic leverage PA. 2 Capital placed as physical escrow under DividendMarker on district. At next Upkeep Step 5: Dominant faction claims it. If no Dominant (Contested or all Absent): marker stays, recheck next Upkeep. Quarter end: Syndicate recovers unclaimed escrow. Voluntary withdrawal: 1 Mandate public declaration. DividendMarker is a new component — Art 02 registration required.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.2', 'arbiter_note', '\"Beat 4: place DividendMarker on district with 2 Capital tokens as physical escrow. Syndicate +1 PS. At each Upkeep Step 5 while marker present: check for Dominant in district. If Dominant: transfer 2 Capital to that faction; remove marker. If Contested or Absent: marker remains for next Upkeep. Phase 21: return unclaimed escrow to Syndicate. Voluntary withdrawal: Syndicate declares to ARBITER, pays 1 Mandate; escrow returned.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'card_id', '\"SYN.PA.3\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'version', '\"v0.1\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'name', '\"Data Acquisition\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'tagline', '\"We know approximately what you\'re holding. We\'re giving you the chance to make this a transaction.\"', '04___Card_System___Part4e_Syndicate.md');
