INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'target_object', 'IntelTokensHeld(count=N_declared)', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'target_freeform', '(\n        N             = int,                         \n        consideration = verbaloffer(faction(acting)),\n        \n    )', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'affinity', 'None', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'restriction', 'None', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'cost', 'Capital * 1', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'boost', 'None', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'on_accept', '(\n        \n        consideration.move(faction(acting), faction(target)),          \n        IntelToken(N_declared).move(faction(target).terminal,\n                                    faction(acting).terminal),         \n        \n        \n\n        \n        \n        \n    )', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'on_decline', 'faction(acting).standing.remove(2)', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'persistence', 'Permanent', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'persistence_condition', 'NOT (Quarter.ended OR react_fired OR terms_accepted)', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'persistence_effect', 'React(\n        trigger = faction(target).PA(target_profile != None).placed_at(\"Art 03 §9.2.0\"),\n        effect  = target_profile.replace(Syndicate.written),\n        on_fire = SYN_PA_3 → faction_PA_discard,\n    )', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'portrait', '{Syndicate: PortraitEntry(submitter=+1)}', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'ps_framing', 'None', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'narrative', '\"The offer is made in public, which is unusual for the Syndicate. They prefer quiet transactions. This one is designed to be loud.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'perspectives', '{\n        Syndicate:   \"Intelligence is a commodity. We\'re establishing the market price and giving them the chance to sell at it.\",\n        Ghost:       \"The offer is a probe. The response — whatever form it takes — is the data.\",\n        Network:     \"This is how private information becomes public leverage. This is exactly what we exist to counter.\",\n        Directorate: \"A public extortion offer dressed as commerce. We note the terms and the response.\",\n        Guild:       \"Whatever they\'re buying, they think they need it. That tells us something about their position.\",\n    }', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'design_note', '\"Three resolution paths at Beat 4 ElectPlayer: (1) trade — bilateral exchange: consideration moves Syndicate→target, N tokens move target→Syndicate; card discards only if both transfers complete; (2) show — target reveals all held tokens face-down (count public, content private), no transfer, card discards — information goal met; (3) decline — no reveal, no trade, Syndicate −2 PS, card becomes Permanent. Sub-cases 1 (completed) and 2 both satisfy the card; only 3 triggers the stake. Non-fulfillment edge case (sub-case A, Syndicate cannot deliver consideration): exchange fails; card stays Permanent — Syndicate set the terms and failed to meet them. Bluff mechanic is intentional: consideration is a verbal offer written on TP declared-parameters line, not held in escrow; Syndicate bears public failure risk. Show path: target voluntarily reveals count — not compelled, consistent with GR 10.1 (ElectPlayer creates stake; choice is player\'s). PERMANENT PHASE is fully table-enforced: card is face-up in Syndicate PA area; table observes when target places a PA with Target Profile at Art 03 §9.2.0 and allows Syndicate to replace it (React); table observes if target accepts at any point (trade or show) and card is cleared. No ARBITER involvement required at any stage — Beat 4 ElectPlayer is public; Permanent card is table-enforced. Target may accept at any time to clear the card. Threat is the constraint: target must deal with Syndicate or avoid targeted PAs for the rest of the Quarter. N and consideration declared at Art 03 §9.2 on TP declared-parameters line (Art 02 v2.4). `consideration` is free-text (`verbaloffer()`): Capital, a named ModifierCard, or any combination. The Permanent-phase React only fires on a PA with a non-blank Target Profile — a PA type with no Target Profile (e.g., the Floor Act) does not trigger it.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.PA.3', 'arbiter_note', 'None', '04___Card_System___Part4e_Syndicate.md');
