INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.MOD.8', 'narrative', '\"The paperwork was drafted before the demolition crew finished clearing the site. Syndicate doesn\'t wait for the dust to settle to make an offer.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.MOD.8', 'perspectives', 'None', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.MOD.8', 'design_note', '\"Vulture Fund is distinct from SYN.CA.9, an unrelated card that displaces an opponent\'s active presence tokens. Vulture Fund is a different mechanic entirely: opportunistic expansion into vacated ground, not a forced acquisition of a going concern. When a structure falls, Syndicate swoops in, paying 2 Capital to immediately place both a presence chip and a structure in the newly cleared real estate. Extremely powerful territorial swing funded entirely by Capital Cost reasoning: Exposure ensures the takeover is recognized publicly, legitimizing the new ownership immediately.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.MOD.8', 'arbiter_note', 'None', '04___Card_System___Part4e_Syndicate.md');
