INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.MOD.10', 'design_note', '\"Resolution layer gap fill. Fills \'money-at-the-table\' narrative: Syndicate pays Capital to suppress a named faction\'s PA threshold at the moment of declaration. ARBITER places −15 modifier token on target PA\'s Beat 4 resolution row. Named target faction declared when card is played/assigned (before §9.2). Single-fire Immediate — discards after triggering. Outstanding: (1) Trigger pattern public_act.placed_on_frg(faction(target)) — existing confirmed examples are self-targeting (Network\'s own PAs); confirm opponent-targeting variant is procedurally valid. (2) Named faction pre-declaration timing — confirm ARBITER can track the target faction designation without revealing Syndicate\'s intent.\"', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_body (card_id, field_name, raw_value, source_file) VALUES ('SYN.MOD.10', 'arbiter_note', '\"On trigger (named target faction places PA at §9.2): Syndicate pays Capital×1. Place modifier token (−15) on target PA\'s Beat 4 resolution row. Announce modifier publicly (target PA threshold is reduced by 15; acting faction not identified). Card discards after firing.\"', '04___Card_System___Part4e_Syndicate.md');
